(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fo"] = {"ui":{"skip":"Far til innihaldið","back":"← Aftur til AI-gile","lang.button":"Mál: {name}","lang.dialog":"Vel eitt mál","lang.search":"Leita eftir máli","lang.none":"Einki mál hóvar","lang.notYet":"{name} er ikki umsett enn","theme.aria":"Skift hátt: ljósur, myrkur ella svartur","theme.toLight":"Skift til ljósan hátt","theme.toDark":"Skift til myrkan hátt","theme.toBlack":"Skift til svartan hátt (veruliga svartur, góður fyri OLED-skermar)","words.underline":"Strika undir hesi orðini á síðuni","words.underlineHelp":"Halt músina yvir ella trýst á eitt prikkað orð fyri at síggja, hvat tað merkir.","words.col.todo":"Kort valt til nú: toymið byrjar við hesum næst.","words.col.doing":"Ein AI arbeiðir við hetta kortið beint nú.","words.col.review":"Ein AI hevur gjørt arbeiðið; ein annar kannar tað, áðrenn tað kemur til tín.","words.col.verify":"Bíðar eftir tær: royn tað og sig, um tað riggar.","words.col.team":"Tínar notur ella svar, sum bíða eftir, at toymið tekur tey.","words.col.done":"Liðugt og góðkent.","index.title":"AI-gile: títt AI-menningarlið, á einum borði","index.description":"AI-gile er eitt kanban-borð til AI-kodulið. Tey arbeiða meðan tú sovir; tú fært ein stuttan bunka við tilfarið at taka avgerð um, royna og góðkenna.","hero.logoAlt":"AI-gile borðtekn","hero.h1.html":"Títt AI-menningarlið, á einum&nbsp;borði.","hero.alpha":"🐣 Lukkað pre-alfa","hero.alphaTitle":"Tíðliga og ikki liðugt: takk fyri at royna!","hero.lede":"Tey byggja meðan tú sovir. Tú vaknar til ein stuttan bunka: nøkur spurningar, nøkur at royna, ein ella tveir purpurdiamantir. Klikk, góðkent, aftur til kaffibollan.","dl.windows":"Windows-app","dl.browser":"Brúka í kagarinum","dl.messenger":"📱 Messenger til fartelefonina","dl.soon":"Kemur skjótt","dl.notify":"🔔 Boða mær frá, tá tað letur upp","dl.notifySmall":"Alfa ella beta","hero.secondary":"Agile, men liðið hevur ongantíð brúk fyri standandi-fundar-kaffi. (Tey hava standandi fund kortini.)","pitch.h2":"AI-gile í so nógvum orðum, sum tú vilt","pitch.lede":"Vel eina longd, frá einum orði upp í 144. Hvør longd er sín egni frágreiðing, skrivað til tann stødd. Drag rennuna ella brúka pílarnar.","pitch.rangeLabel":"Longd í orðum","pitch.dice":"🎲 ein onnur útgáva","pitch.words.one":"{n} orð","pitch.words.other":"{n} orð","pitch.letters.one":"{n} bókstavur","pitch.letters.other":"{n} bókstavir","pitch.chars.one":"{n} tekin","pitch.chars.other":"{n} tekin","count.line.html.one":"{n} kort á borðinum júst nú","count.line.html.other":"{n} kort á borðinum júst nú","people.humans.html.one":"👥 {n} menniskja","people.humans.html.other":"👥 {n} menniskjur","people.agents.html.one":"🤖 {n} agentur","people.agents.html.other":"🤖 {n} agentar","people.working.html.one":"⚡ {n} í arbeiði júst nú","people.working.html.other":"⚡ {n} í arbeiði júst nú","pre.title":"AI-gile: her verður nakað bygt","pre.description":"Her verður nakað bygt. Eitt borð, har AI-lið byggja tað, tú biður um, og læra teg á vegnum. Fyribils eitt lukkað pre-alfa við vinum.","pre.h1":"Her verður nakað bygt. 🤫","pre.line":"Eitt borð, har AI-lið byggja tað, tú biður um, og læra teg á vegnum. Fyribils eitt lukkað pre-alfa við vinum.","pre.btn":"🔔 Boða mær frá, tá tað letur upp","pre.peek":"Aftanfyri glasið: veruliga borðið, beinleiðis. Hvørt kort er ein litaður strikur.","pre.peekFake":"Aftanfyri glasið: soleiðis sær eitt borð í arbeiði út.","pre.night":"🌙 Næturvaktin hevur ræðið · 😴 menniskjan hvílist","features.aria":"Hvat tað ger","f.pile.h":"Ein bunki til tín","f.pile.html":"<b>Fyri teg</b> inniheldur alt, sum bíðar eftir tær, í øllum verkætlanum: spurningar, tilfar at royna, uppgávur, sum bara ein maður kann gera. Tín bíðirøð sigur, hvat er næst og hvussu leingi tað tekur.","f.sleep.h":"Lið, sum arbeiða meðan tú sovir","f.sleep.p":"Hvør verkætlan hevur ein leiðara og eitt lið av AI-agentum. Skriva eina viðmerking á eitt kort, og liðið vaknar, ger arbeiðið og gevur tær tað aftur við stigum, sum eisini ein móður maður kann fylgja.","f.tester.h":"Ein AI-royndari kannar fyrst","f.tester.p":"Áðrenn nakað kemur til tín, fylgir ein royndari stigunum í einum avriti av appini og vísir, hvat hann sá, við skíggjamynd. Blaða tú gjøgnum tey, sum eru greidd, og góðkenn við einum klikki.","f.proof.h":"Prógv, ikki lyfti","f.proof.p":"Hvør yvirlatan vísir, hvat broytt er: fílurnar, diff-ið, skíggjamyndirnar. Tú sleppur undan at lata hvørt app upp fyri at sæa, um tað er liðugt.","f.chat.h":"Práta við leiðararnar hjá tær","f.chat.p":"Ein Discord-líknandi rekki: eitt tekn fyri hvørja verkætlan, purpurdiamantir fyri tað, sum hevur brúk fyri tær. Send leiðaranum eitt hugskot; hann ger kort og eina ætlan burturúr, við einum ✅ Go-knappi.","f.tidy.h":"Heldur seg sjálvt rættiliga","f.tidy.p":"Kort, sum hanga saman, renna saman, ruglaðir heitir verða rættaðir, og ein tokenkanning heldur kodu lættari. Færri ting at skifta millum, minni at hugsa um.","f.private.h":"Títt, á tíni teldu","f.private.li1":"Borðið koyrir á tínari egnu maskinu og svarar bara tær.","f.private.li2":"Privatar boð millum fólk eru enda-til-enda krypterað.","f.private.li3":"Eingin konta, ongir fylgjarar, ongar cookies.","f.lang.h":"Á tínum máli","f.lang.p":"Meiri enn 120 mál, frá hollendskum, valisiskum og japanskum til sjóræningamál, Yoda og klingonskt, við skjótum skifti aftur til enskt fyri fakorðini.","f.service.h":"Frá einum hugskoti til eina veruliga tænastu","f.service.p":"Hevur tú bygt okkurt við AI, sum fólk nú nýta? Merk tað sum tænastu, og borðið hjálpir tær at reka tað væl: uppi-tíðar eftirlit, ein almenn støðusíða, hendingar við frágreiðing, broytingar, sum krevja eitt Go, og trygdaravrit, ið verða kannað dagliga. Hjálpin lærir teg hvørt stig, so hvørt tú fert fram.","msgr.h2":"AI-gile Messenger: toymið í lummanum","msgr.p1":"Tosa við AI-toymið uttan at lata borðið upp. Kjatta við verkætlanarleiðararnar og vinirnar, og síggj royndarstigini á einum korti og svara teimum, alt frá fartelefonini.","msgr.p2":"Skanna ein QR-kotu á borðinum fyri at para. Fyrstu ferð? Eitt vinarligt demo-kjatt vísir tær runt.","msgr.when":"Fyrst Android, síðan ein vevútgáva til fartelefonir og iPhone.","msgr.who":"Verkætlanarleiðarin hjá tær","msgr.b1":"Rættingin til myrka háttin er klár. Vilt tú hava royndarstigini?","msgr.b2":"Ja takk!","msgr.b3":"1. Lat Stillingar upp. 2. Vel Myrkt. Sær tað rætt út?","tl.aria":"Tíðarlinja frá fyrsta samrøðu til vegakortið","tl.h2":"Frá fyrstu práti til tað, sum er næst","tl.lede":"Veruligar dagar og tíðir, í tínum egna tíðarsvæði. Aftaná í dag er tað ætlanin, uttan lovaðar dagar.","tl.today":"Í dag","tl.planned":"ætlað","tl.doing":"í gerð","tl.cards.one":"{n} kort","tl.cards.other":"{n} kort","join.h2":"Vertu við","join.lede":"AI-gile verður bygt av einum skeggutum sérlingi við AuDHD og nøkrum stríðum við sálarheilsuna, og av nógvum tolnum agentum. Tað er privat enn, í lukkaðari alfu saman við vinum. Vilt tú royna, tá tað letur upp?","join.btn":"Boða frá áhuga","join.small":"Vit senda tær teldupost, einki annað","footer.tag":"AI-gile. Ongir fylgjarar, ongar cookies, einki standandi-fundar-kaffi.","footer.licence":"Fyritøkuloyvi","footer.status":"Støða","footer.privacy":"Hvat vit goyma","footer.thanks":"Samtalur takk veri ChilledChat","form.sending":"Sendi…","form.failed":"Tað riggaði ikki: royn aftur seinni.","form.offline":"Fekk ikki samband við AI-gile: royn aftur seinni.","form.keep":"Vit brúka hetta bert til at svara tær, síðan strika vit tað. Ongir fylgjarar, ongar cookies.","form.keepLink":"Hvat vit goyma","interest.title":"AI-gile: boða mær frá, tá alfan letur upp","interest.description":"Skriva tín teldupost fyri at frætta, tá lukkaða alfan ella betan hjá AI-gile letur upp.","interest.h1":"🔔 Boða mær frá, tá tað letur upp","interest.lede":"AI-gile er í lukkaðari pre-alfu. Skriva tín teldupost, og vit skriva tær eina ferð, tá pláss er til tín.","interest.email":"Tín teldupostur","interest.which":"Hvør royndin?","interest.alpha":"Lukkað alfa: tíðliga, ruggað, nógvar broytingar","interest.beta":"Beta: støðugari, seinni","interest.both":"Annaðhvørt, hvat so fyrst letur upp","interest.submit":"Set meg á listan","interest.thanks":"Takk! Tú ert á listanum.","licence.title":"AI-gile: fyritøkuloyvi","licence.description":"Brúkar tú AI-gile í tíni fyritøku? Søk um eitt ókeypis fyritøkuloyvi.","licence.h1":"📜 Fyritøkuloyvi","licence.lede":"Brúkar tú AI-gile á arbeiðsplássinum? Sig okkum, hvør tú ert og hvat tú gert. Um tað ger gott, er loyvið ókeypis.","licence.company":"Fyritøka","licence.website":"Heimasíða","licence.what":"Hvat tú gert","licence.how":"Hvussu tað hjálpir heiminum","licence.email":"Teldupostur","licence.submit":"Søk","licence.thanks":"Takk! Vit svara við teldupósti.","status.title":"AI-gile støða","status.h1":"AI-gile støða","status.quiet":"Alt er kvirt","status.intro":"Riggar AI-gile júst nú? Henda síðan kannar heimasíðuna, deiling av talvum, samtalur og niðurtøkuna hvørjar 5 minuttir.","status.up":"Riggar (svaraði eftir {ms} ms)","status.slow":"Svaraði ikki seinastu kanningini, royni aftur","status.down":"Úr gongd: svaraði ikki seinastu tveimum kanningunum","status.svc.web":"Heimasíða","status.svc.web.offers":"Henda síðan: hvat AI-gile er, og áhugaformularin","status.svc.boards":"Deiling av talvum","status.svc.boards.offers":"Almennar talvur, boð millum vinir og innbjóðingar","status.svc.calls":"Samtalur","status.svc.calls.offers":"Rødd, video og skermdeiling í AI-gile","status.svc.download":"Niðurtøka","status.svc.download.offers":"Windows-innleggjarin og innbjóðingarleinkjur","status.checking":"Kanni…","status.offline":"Fái ikki samband við støðutænastuna júst nú (royni aftur)","status.updated":"dagført {ago}","status.justNow":"júst nú","status.min":"{n} min síðani","status.hours":"{n} t síðani","status.days":"{n} d síðani","privacy.title":"AI-gile: hvat vit goyma","privacy.h1":"Hvat vit goyma","privacy.lede":"Stutt sagt: bert tað, tú sendir okkum, og ikki leingi.","privacy.only":"Bert tað, tú sendir okkum: tað, tú skrivar í eitt formular, so sum teldupostin hjá tær. Einki annað um teg.","privacy.sealed":"Tað verður innsiglað, so ambætarin hjá okkum ikki kann lesa tað: í kaganum hjá tær, áðrenn tað fer avstað (á einum eldri kaga, tá ið tað kemur fram). Bert okkara egna talva kann lata tað upp.","privacy.server":"Tað verður strikað av ambætaranum, so skjótt sum tað kemur fram á talvuna hjá okkum. Alt, ið enn liggur har eftir 30 dagar, verður strikað líkavæl.","privacy.board":"Vit goyma tað á talvuni hjá okkum bert, til vit hava svarað tær, síðan strika vit tað har eisini.","privacy.none":"Ongir fylgjarar, ongar cookies, eingin greining.","privacy.local":"Málið hjá tær og valið millum ljóst og myrkt verða verandi í tínum egna kaga. Tey verða ongantíð send til okkara.","privacy.ask":"Vilt tú hava tað burtur fyrr? Svara teldupostinum frá okkum og sig frá.","live.h2":"Sær tað verða bygt, beinleiðis","live.caption":"Hvert kort er fjalt: tú sært skapið á arbeiðinum, ikki orðini.","live.watching.one":"beinleiðis: {n} hyggja","live.watching.other":"beinleiðis: {n} hyggja","live.last.now":"Seinasta kort flutt júst nú","live.last.min.one":"Seinasta kort flutt fyri {n} min síðani","live.last.min.other":"Seinasta kort flutt fyri {n} min síðani","live.last.hour.one":"Seinasta kort flutt fyri {n} tíma síðani","live.last.hour.other":"Seinasta kort flutt fyri {n} tímum síðani","live.last.day.one":"Seinasta kort flutt fyri {n} degi síðani","live.last.day.other":"Seinasta kort flutt fyri {n} døgum síðani","live.offline":"Beinleiðis talvan tekur sær eina løtu at kvíla. Kom aftur skjótt.","live.cols":"Backlog|At gera|Í gerð|Toymið kannar|Fyri teg at testa|Fyri toymið|Liðugt"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotar.","Avgreitt."]},{"n":2,"texts":["Robotar arbeiða.","Agentar, skipaðir.","Hugskot, bygd."]},{"n":3,"texts":["Kanban fyri robotar.","Hugskot verða eyðkenni.","Ókeypis agent-kanban."]},{"n":5,"texts":["Kanban-borð rikið av agentum.","Tú skrivar, agentar byggja.","Ókeypis, lokalt, roynt, eitt sindur tilkomið."]},{"n":8,"texts":["Eitt ókeypis kanban-borð, har AI-agentar arbeiða.","Skriva eitt hugskot. Agentar byggja. Tú góðkennir.","Agile fyri ein mann og nógvar tolnar robotar."]},{"n":13,"texts":["Eitt kanban-borð á tíni teldu, har AI-agentar taka kortini og gera arbeiðið.","Skriva eitt hugskot. Eitt lið av agentum bygger tað. Ein royndari kannar tað.","Ókeypis, eingin konta, ongir fylgjarar: eitt borð, nakrir robotar, og tú ræður."]},{"n":21,"texts":["AI-gile er eitt kanban-borð at arbeiða saman við AI-kodaagentum. Tey taka kortini; tú roynir tey og góðkennir tey.","Hvør verkætlan fær ein leiðara og eitt lið av AI-agentum. Skriva eina viðmerking á hvørt kort, og liðið fer til verka.","Eitt ókeypis, persónligt uppgávuborð, sum koyrir á tíni egnu teldu. Arbeiðararnir eru robotar. Tann, sum sigur ja, ert tú."]},{"n":34,"texts":["Tú leggur hugskot á eitt borð. Eitt lið av AI-agentum ger tey til virkandi eyðkenni, roynir tey og gevur tær tey aftur við stigum at royna. Einki telst sum liðugt, fyrr enn tú sigur tað.","AI-gile er eitt heimagjørt kanban-borð, sum Rich bygdi við nógvari hjálp frá teimum agentum, sum tað nú stýrir. Tað er ókeypis, koyrir á tíni teldu og verður deilt við vinir, ikki selt.","Hugsa tær eitt vanligt kanban-borð, við súlum frá Backlog til Liðugt, nema at kortini verða tikin av AI-agentum. Tey boða frá framgongd, spyrja, tá tey sita fast, og bíða altíð eftir tínari góðkenning."]},{"n":55,"texts":["AI-gile er eitt kanban-borð, har liðið er gjørt av AI-agentum. Hvør verkætlan hevur ein leiðara, sum ætlar arbeiðið, og hjálparar, sum byggja tað. Tá eitt eyðkenni er klárt, roynir ein AI-royndari tað og tekur eina skíggjamynd, síðani kemur tað í tín bunka. Góðkenn tað, ella skriva eina viðmerking, og tey gera tað umaftur.","Tað byrjaði sum háttur hjá einum manni at fylgja við í nógvum AI-kodusessiónum í senn, og vaks til eitt veruligt borð. Tað koyrir á tíni maskinu, krevur onga kontu og hevur ongar fylgjarar. Tað er ókeypis fyri vinir og forvitin. Tað er eisini ikki liðugt, so ríkna við rúgvum kantum og einstaka undran.","Her er sanna útgávan. Tú mást enn hava hugskotini, og tú mást enn kanna úrslitini. Tað, sum AI-gile ger, er alt hitt ímillum: tað heldur kortunum í røð, vekur røttan agent, tá tú skrivar viðmerking, vísir júst hvat broytt er, og leggur alt í ein stuttan bunka til tín."]},{"n":89,"texts":["AI-gile er eitt ókeypis kanban-borð, sum tú letur koyra á tíni egnu teldu. Í staðin fyri fólk hevur hvør verkætlan eitt lið av AI-agentum: ein leiðara, sum ger hugskotini hjá tær til kort og eina ætlan, og hjálparar, sum taka kortini í raðfylgju eftir týdningi. Tá okkurt er bygt, fylgir ein AI-royndari royndarstigunum og vísir tær, hvat hann sá. Síðani bíðar tað í einum bunka, sum eitur Fyri teg. Tú góðkennir tað, ella tú skrivar eina viðmerking, og liðið roynir enn eina ferð. Einki kemur nakrantíð til Liðugt uttan teg.","Nøkur eyðkenni, sum tú kanska ikki væntar. Ein náttarvakt heldur súlini At gera fullari, meðan tú sovir, og velur kort, sum ikki hava brúk fyri svari frá tær. Ein tokentalari vísir, hvussu nógv agentarnir hava brúkt í dag og hesa vikuna, og Eingin token-hátturin sigur teimum at steðga at brúka. Tú kanst senda vinum boð, og privat boð eru enda-til-enda krypterað. Borðið tosar umleið 120 mál, millum annað hollendskt, flamskt, sjóræningamál og klingonskt. Einki av hesum kostar ein oyra, og ongin roynir at selja tær tað.","AI-gile er eitt lítið, persónligt tiltak, ikki ein fyritøka. Rich vildi taka sær av fleiri AI-kodaverkætlanum uttan at lata hvørt app upp fyri at kanna tær, so hann og agentarnir bygdu eitt borð til tað, og brúktu síðani borðið til at byggja restina av sær sjálvum. Tað er í lukkaðari pre-alfu, sum merkir, at tað riggar, mestsum, fyri ein bólk av vinum. Her er eingin prísasíða, einki fregnbræv og ongin vøkstrarætlan. Um tað ljóðar nyttigt, kanst tú biðja um at royna tað, tá tað letur eitt sindur meiri upp."]},{"n":144,"texts":["AI-gile er eitt kanban-borð fyri ein mann og nógvar AI-agentar. Tað koyrir á tíni egnu teldu og er heilt ókeypis. Tú leggur verkætlanir afturat, og hvør verkætlan fær ein leiðara og eitt lítið lið. Tú prátar við leiðaran, eitt sindur sum á Discord, og lýsir eitt hugskot; leiðarin ger kort og eina ætlan burturúr og bíðar síðani eftir, at tú trýstir á Go. Liðið arbeiðir seg gjøgnum kortini í raðfylgju eftir týdningi, við einari einfaldari boðraðlinju gjørdari til málmodellir. Áðrenn nakað kemur aftur til tín, fylgir ein AI-royndari stigunum í einum avriti av appini og leggur eina skíggjamynd við. Liðugt arbeiði kemur í tín bunka við broyttum fílum og diff-inum. Tú góðkennir tað, ella tú letur eina viðmerking eftir, og liðið vaknar og roynir aftur. Bara tú kanst flyta eitt kort til Liðugt.","Ein dagur við AI-gile, umleið. Um kvøldið letur tú nøkur viðmerkingar eftir: hesin knappurin er á skeivum stað, hin listin eigur at vera raðfest, kundi tað eisini fingið myrkan hátt. Tú fert í song. Agentarnir lesa viðmerkingarnar, gera broytingarnar, royna tær og geva tær aftur til tín. Um At gera tæmist, fyllir náttarvaktin tað úr backlog við kortum, sum ikki hava brúk fyri svari frá tær. Um morgunin er ein stuttur bunki: nøkur spurningar og nøkur ting at royna, hvørt við stigum, sum ein søvnugur maður kann fylgja, og skíggjamynd av, at tað riggar. Tú klikkar teg gjøgnum, góðkennir tey góðu og sendir restina aftur. Ein tokentalari vísir, hvat alt hetta brúkti, og Eingin token-hátturin er til tær magru vikurnar. So etur tú morgunmat, sum agentarnir ikki kunnu hjálpa við enn.","Fyrst, hvat AI-gile ikki er. Tað er ikki ein startup, tað er ikki til sølu, og ongin savnar tínar dátur. Tað er eitt ókeypis borð, sum koyrir á tíni teldu, uttan kontur, uttan fylgjarar og uttan cookies. Hvat tað er: ein rættilig støð at sæa allar AI-kodaverkætlanirnar í senn, við einum liði av agentum, sum gera kortini, og tær, sum taka avgerðirnar. Tað rennur kort saman, sum hanga saman, rættar ruglaðar heitir, og hevur eyga við, um kodan verður verandi lætt. Tað tosar umleið 120 mál, frá hollendskum og flamskum til sjóræningamál og klingonskt. Vinir kunnu senda hvønn øðrum boð, privat og krypterað. Tað varð bygt av Rich og nógvum tolnum agentum, mestsum við at brúka seg sjálvt. Tað er í lukkaðari pre-alfu, so tað er ruggað sums staðni. Um tað ljóðar stuttligt, bið vælsiðað, og kanska sleppur tú tíðliga inn."]}],"quips":{"1":"Eitt orð. Djarvt. Kanska ov djarvt.","3":"Trý orð. Longu ærligari enn flestu vøruvevir.","8":"Átta orð. Enn styttri enn ein standandi fundur.","21":"Longdirnar eru annars story points. Sjálvsagt eru tær tað.","55":"Fimmtiofimm orð. Tvey kort vórðu liðug, meðan tú las hetta.","144":"Hetta er tann langa. Ongin 233 er til. Agentarnir eru farnir í song."}},"timeline":{"first-idea.name":"Fyrsta hugskotið","first-idea.line":"Fyrsta samrøða av øllum, áðrenn nøkur koda var til.","first-board.name":"Fyrsta borð","first-board.line":"Eitt borð, sum fylgir sínum egna bygnaði: kort, súlur, drag og slepp, verkætlanir.","team-roles.name":"Lið og leiklutir","team-roles.line":"Agentprofilir, liðsmynstur, rúm og hvør ger hvat.","install.name":"Uppsetan og útgávur","install.line":"Ein zip, sum ein vinur kann seta upp, sjálvdagføring, rásir og afturrulling.","usage-saver.name":"Nýtslusparing","usage-saver.line":"Máta hvat koyringar kosta, halda kodu lættari, spara markið hjá tær.","friends.name":"Vinir og deiling","friends.line":"Privatar boð, ruglað relay, innbjóðingar, leiklutir og deild verkætlanir.","languages.name":"Mál","languages.line":"Hvør skíggjatekstur í einari málfílu, við hollendskum og flamskum fyrst.","ai-tester.name":"AI-royndari","ai-tester.line":"Ein royndari kannar hvørja yvirlatan fyrst og vísir, hvat hann sá.","website.name":"Heimasíðan","website.line":"aigile.lol, teaserin og henda tíðarlinjan.","streaming.name":"Prát og streymur","streaming.line":"Discord, Twitch, OBS, streymarahættur, GIF og emojir.","no-ai.name":"Útgáva uttan AI","no-ai.line":"Eitt borð til tey, sum koda uttan AI, og almenn borð.","night-watch.name":"Náttarvakt","night-watch.line":"Ein vaktari og ein Scrum Master halda liðunum við uppgávuna meðan tú sovir.","p-more.name":"Alt annað","p-more.line":"Smærri hugskot, sum bíða enn eftir síni tøk.","p-android.name":"Telefon og Android","p-android.line":"Kom til borðið hjá tær frá telefonini, síðani eitt upprunaligt Android-app.","p-release.name":"Alfa og longri","p-release.line":"Lukkað alfa, livandi heimasíðan, síðani beta.","p-languages.name":"Fleiri mál","p-languages.line":"130 mál, og ein málsdýpdarstøða til tey, ið læra.","p-engines.name":"Fleiri AI-motorar","p-engines.line":"Vel Claude, Codex, Gemini, Copilot ella Cursor fyri hvønn agent.","p-pro.name":"Fakligur háttur","p-pro.line":"Vandamerki, samanrenningarbørur, hendingarkort og rekkverk.","p-self.name":"Varða um teg","p-self.line":"Móðurhættur, sjálvsrøktaráminningar og 4:20.","p-servers.name":"Ambætarar og vøkstur","p-servers.line":"Almennar ambætaraskipanir, leiklutir og ætlan fyri vøkstri.","p-livestream.name":"Streymiískoyti","p-livestream.line":"Twitch-prát, egnar emojir og eitt almennt beinleiðis sjónarhorn."},"words":{"button":"📖 Fakorð","h":"📖 Orð greitt frá","intro":"Ókeypis læring á einføldum máli: hvørt orð, tú møtir, frá fyrsta hugskoti til eina tænastu, sum fólk líta á, við Agile, bygging, trygd og arbeiði við AI á vegnum.","search":"Leita eftir einum orði…","none":"Einki orð samsvarar.","close":"Lat aftur","count":{"one":"{count} orð","other":"{count} orð"},"groups":[{"id":"idea","name":"💡 Hugskot og kanning"},{"id":"plan","name":"🗺️ Arbeiðið lagt til rættis"},{"id":"agile","name":"🔁 Agile arbeiðsmáti"},{"id":"build","name":"🛠️ At byggja"},{"id":"test","name":"🧪 Royndir og gæði"},{"id":"change","name":"🔀 At broyta trygt"},{"id":"run","name":"🛎️ At reka eina tænastu"},{"id":"sec","name":"🔒 Trygd og privatlív"},{"id":"ai","name":"🤖 At arbeiða við AI"},{"id":"money","name":"💰 Peningar og loyvi"}],"list":[{"id":"discovery","g":"idea","word":"Kanning","text":"Fyrsta stigið, har tú finnur út av, hvør trupulleiki er vert at loysa og fyri hvønn, áðrenn nakað verður bygt.","also":["kanningarstig"]},{"id":"problemstmt","g":"idea","word":"Trupulleikalýsing","text":"Ein ella tvær setningar, sum siga, hvør hevur ein trupulleika, hvat hann er og hví hann hevur týdning, so øll sigta eftir tí sama.","also":["trupulleikalýsingar"]},{"id":"user","g":"idea","word":"Brúkari","text":"Ein persónur, sum brúkar tað, tú byggir. Arbeiðið er til fyri at nøkta tørv hansara.","also":["brúkarar"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Áhugapartur","text":"Hvør tann, sum hevur áhuga í, hvussu arbeiðið endar, ella sum verður rakt av tí, til dømis tey, sum rinda fyri tað, brúka tað ella veita stuðul til tað.","also":["áhugapartar"]},{"id":"persona","g":"idea","word":"Persóna","text":"Ein uppdiktaður, men trúligur persónur, sum stendur fyri eitt slag av brúkara, so toymið kann spyrja: “Hevði Sam funnið hetta lætt?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"Brúkarakanning","text":"At práta við og hyggja at veruligum fólki fyri at læra, hvat tey hava brúk fyri, heldur enn at gita.","also":["brúkaraviðtalur"]},{"id":"journey","g":"idea","word":"Brúkaraferð","text":"Skrefini, sum ein persónur tekur fyri at fáa okkurt gjørt, frá fyrstu løtu hann hoyrir um tað til tað er liðugt, eisini uttan fyri tína vøru. At teikna tað sýnir, hvar hann situr fastur.","also":["brúkaraferðir","kundaferð"]},{"id":"painpoint","g":"idea","word":"Pínupunkt (pain point)","text":"Okkurt, sum í dag ergir fólk ella heldur teimum aftur. Góðar vørur taka pínupunkt burtur.","also":["pínupunkt","pain point","pain points"]},{"id":"assumption","g":"idea","word":"Fyritreyt","text":"Okkurt, sum tú heldur er satt, men ikki hevur kannað enn. At skriva fyritreytirnar niður vísir, hvat tú skalt royna fyrst.","also":["fyritreytir","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypotesa","text":"Tín besta giting, sum tú ætlar at kanna, saman við tí, sum tú væntar fer at henda, til dømis “fólk skráseta seg, um fyrsti mánaðurin er ókeypis”.","also":["hypotesur","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Eksperiment","text":"Ein lítil, ætlað roynd fyri at fáa at vita, um eitt hugskot riggar, áðrenn tú setur nógv á spæl fyri tað.","also":["eksperiment","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Hugskotsprógv (PoC)","text":"Ein skjót, grov roynd fyri at síggja, um eitt hugskot yvirhøvur kann rigga. Vanliga verður hon kastað burtur, tá ið tú hevur svarið.","also":["PoC","hugskotsprógv","proof of concept"]},{"id":"prototype","g":"idea","word":"Frumsnið","text":"Eitt tíðligt módel av vøruni, ofta myndir, ið kunnu trýstast á, fyri at royna hugskotið á fólki, áðrenn tú byggir tað veruliga.","also":["frumsnið"]},{"id":"wireframe","g":"idea","word":"Skermskitsa (wireframe)","text":"Ein einføld skitsa av einum skermi, sum vísir, hvar tingini skulu standa, uttan litir og veruligt innihald.","also":["skermskitsur","wireframe","wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Ein nágreinilig mynd av, hvussu ein skermur fer at síggja út, við veruligum litum og teksti, men einki riggar enn.","also":["mockups","mock-up","mock-ups","útsjóndarmynd"]},{"id":"bizcase","g":"idea","word":"Business case","text":"Grundirnar fyri at gera eina verkætlan: hvat hon kostar, hvat hon gevur av sær ella sparir, og hvørjir váðar eru.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Gjørligleiki","text":"Um okkurt veruliga kann byggjast og røkjast við tí tíð, peningum og førleika, sum tú hevur."},{"id":"outcome","g":"idea","word":"Úrslit","text":"Broytingin, sum tú vilt fáa til vega fyri fólk, til dømis at færri gloyma tíðirnar hjá sær. Hon hevur størri týdning enn, hvussu nógv tú byggir.","also":["úrslit"],"noTip":1},{"id":"output","g":"idea","word":"Avrik (output)","text":"Okkurt, sum toymið ger, til dømis ein nýggjan skerm ella eina frágreiðing. At gera tað merkir ikki sjálvsagt, at tað hjálpir nøkrum.","also":["output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Framgangsmát","text":"Eitt tal, sum sigur, um arbeiðið gjørdi tað, tað var ætlað til, til dømis at fleiri gera bíleggingina liðuga.","also":["success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Lykiltal (KPI)","text":"Eitt týdningarmikið tal, sum tú fylgir við, fyri at síggja, um tingini ganga væl, til dømis nýggjar skrásetingar um vikuna.","also":["KPI","KPIs","lykiltal","key performance indicator"]},{"id":"okr","g":"idea","word":"Mál og lykilúrslit (OKR)","text":"Ein máti at seta sær mál: málið sigur, hvat tú vilt, og nøkur fá lykilúrslit eru tølini, sum vísa, at málið er nátt.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Vøra","text":"Tað, sum verður bygt og røkt fyri brúkararnar, til dømis eitt app, ein heimasíða ella eitt amboð.","also":["vørur"],"noTip":1},{"id":"vision","g":"plan","word":"Framtíðarsýn fyri vøruna","text":"Ein stutt frágreiðing um, hvørjum vøran hjálpir, og hvar hon stevnir til longdar.","also":["product vision","vision statement"]},{"id":"po","g":"plan","word":"Vøruábyrgdari (PO)","text":"Persónurin, sum avger, hvat verður bygt og í hvørjari raðfylgju, so toymið altíð arbeiðir við tí týdningarmesta. Í AI-gile ert tað tú.","also":["PO","vøruábyrgdarar"]},{"id":"pm","g":"plan","word":"Vørustjóri (PM)","text":"Persónurin, sum hevur ábyrgd av kósini hjá vøruni: hvørjir trupulleikar hon loysir, fyri hvønn og hví. PM kann eisini merkja verkætlanarstjóri, so kanna, hvat er meint.","also":["vørustjórar"]},{"id":"projmgr","g":"plan","word":"Verkætlanarstjóri","text":"Persónurin, sum heldur eina verkætlan innan tíðarfreist og fíggjarkarm og fylgir við, hvør ger hvat og nær.","also":["verkætlanarstjórar"]},{"id":"roadmap","g":"plan","word":"Vegakort","text":"Ein grov ætlan yvir, hvat kemur komandi mánaðirnar, í raðfylgju. Hon vísir kósina, ikki neyvar dagfestingar, og broytist so hvørt, sum tú lærir.","also":["vegakort"]},{"id":"milestone","g":"plan","word":"Áfangi","text":"Eitt punkt í einari verkætlan, sum er vert at merkja, til dømis “fyrsta útgáva úti” ella “100 brúkarar”.","also":["áfangar"]},{"id":"mvp","g":"plan","word":"Minsta brúkiliga vøra (MVP)","text":"Minsta útgávan av einari vøru, sum framvegis er nyttig fyri veruligt fólk, so tú kanst læra av teimum tíðliga.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Krav","text":"Okkurt, sum liðuga vøran skal gera ella vera.","also":["krøv"],"noTip":1},{"id":"scope","g":"plan","word":"Umfatan (scope)","text":"Hvat er við í arbeiðinum, og, líka týdningarmikið, hvat ikki er.","also":["scope","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep (vaksandi umfatan)","text":"Tá ið alt meira smátt um smátt verður lagt afturat arbeiðinum, uttan at nakar hevur samtykt eyka tíðina ella kostnaðin, so tað aldri verður heilt liðugt.","also":["scope creep","feature creep"]},{"id":"feature","g":"plan","word":"Funktión","text":"Okkurt, sum vøran kann gera fyri fólk, til dømis “nullstilla loyniorðið”.","also":["funktiónir","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Eitt stórt arbeiðsstykki, ov stórt at gera í einum, so tað verður býtt sundur í smærri kort.","also":["epics"]},{"id":"story","g":"plan","word":"Brúkarasøga","text":"Eitt lítið arbeiðsstykki, skrivað frá sjónarhorni brúkarans: “Sum keypari vil eg goyma kurvina, so eg kann gera keypið liðugt seinni.” Tað setur í gongd eina samrøðu um, hvat skal byggjast.","also":["brúkarasøgur"]},{"id":"ac","g":"plan","word":"Góðkenningarkrøv (AC)","text":"Kanningarnar, sum eitt kort skal klára fyri at telja sum liðugt, avtalaðar áðrenn arbeiðið byrjar, til dømis “kurvin er enn har, eftir at eg havi ritað út og inn aftur”.","also":["góðkenningarkrøv"]},{"id":"task","g":"plan","word":"Uppgáva","text":"Eitt einstakt starv at gera, ofta eitt lítið stig í einari størri brúkarasøgu.","also":["uppgávur"],"noTip":1},{"id":"ticket","g":"plan","word":"Seðil","text":"Eitt annað orð fyri kort: eitt arbeiðsstykki ella ein umbøn, sum verður fylgd frá byrjan til enda.","also":["seðlar"]},{"id":"priority","g":"plan","word":"Raðfesting","text":"Hvussu týdningarmikið ella áríðandi okkurt er í mun til alt annað, so tað týdningarmesta arbeiðið kemur fyrst.","also":["raðfestingar"],"noTip":1},{"id":"prioritise","g":"plan","word":"At raðfesta","text":"At seta arbeiðið í raðfylgju eftir týdningi. Ein vanligur máti er MoSCoW: Má hava, Eigur at hava, Kundi verið við, Verður ikki við hesaferð.","also":["raðfesta","prioritisation","MoSCoW"]},{"id":"estimate","g":"plan","word":"Støddarmeting","text":"Tín besta giting um, hvussu stórt ella langt eitt arbeiðsstykki er. Tað er ein giting, ikki eitt lyfti.","also":["støddarmetingar","estimate","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points (søgustig)","text":"Ein máti at gita støddina á arbeiði við at bera kortini saman sínámillum (“umleið tvær ferðir so stórt sum hatta”) heldur enn í tímum. Tey eru ikki til at bera toymi saman við.","also":["søgustig","story point"]},{"id":"tshirt","g":"plan","word":"T-bolsstødd","text":"At gita støddina á arbeiði sum S, M, L ella XL. Skjótt og nóg gott til tíðliga ætlanararbeiðið.","also":["t-bolsstøddir"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Ein leikur til at meta um stødd: øll vísa eitt støddarkort samstundis, og síðan greiða tey við hægsta og lægsta kortinum frá, hví.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Avhengi","text":"Tá ið eitt arbeiðsstykki ikki kann byrja ella verða liðugt, fyrr enn eitt annað er komið so langt.","also":["dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Forðing","text":"Alt, sum júst nú forðar arbeiðinum í at koma víðari, til dømis eitt svar, sum vantar, ella eitt amboð, sum er í ólagi.","also":["forðingar"]},{"id":"deadline","g":"plan","word":"Freist","text":"Dagurin, tá ið okkurt í seinasta lagi skal vera liðugt.","also":["freistir"],"noTip":1},{"id":"deliverable","g":"plan","word":"Avlevering","text":"Okkurt handfast, sum arbeiðið ger og letur frá sær, til dømis ein síða, sum riggar, ella ein frágreiðing.","also":["avleveringar"]},{"id":"forecast","g":"plan","word":"Forsøgn","text":"Ein spádómur um, hvat sannlíkt hendir, til dømis nær arbeiðið er liðugt, grundað á tað, sum tú veitst higartil.","also":["forsøgnir"],"noTip":1},{"id":"metric","g":"plan","word":"Máltal","text":"Alt, sum tú mátar og fylgir yvir tíð, til dømis síðuvitjanir ella hvussu leingi tað tekur at rætta eina villu.","also":["máltøl"]},{"id":"feedback","g":"plan","word":"Afturboð","text":"Tað, sum fólk siga tær um títt arbeiði, bæði gott og ringt. At fáa tað tíðliga og ofta er hjartað í Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Bíðilistin yvir hugskot og arbeiði, sum enn ikki er ætlað, við tí týdningarmesta ovast. Einki har verður arbeitt við, fyrr enn tað verður flutt til At gera."},{"id":"sprint","g":"agile","word":"Sprint","text":"Eitt stutt, ásett arbeiðsskeið (ofta ein ella tvær vikur, aldri meira enn ein mánaður) við einum máli og einum avtalaðum setti av kortum at gera liðug.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Ein skjótur dagligur fundur: hvat hvør toymislimur gjørdi, hvat hann ger næst, og hvat forðar honum. Í Scrum verður hann kallaður dagligi scrum.","also":["standup","stand-ups","daily scrum","daily stand-up","standup-fundur"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Ein arbeiðsmáti, har kort flyta seg yvir súlurnar á einum borði (til dømis At gera, Í gerð, Liðugt), og toymið avmarkar, hvussu nógv er í gerð í senn, so arbeiðið heldur fram at flyta seg."},{"id":"wip","g":"agile","word":"WIP-mark","text":"WIP er stytt fyri work in progress. Eitt WIP-mark er tað mesta talið av kortum, sum ein súla eigur at hava í senn, so toymið ger ting liðug, áðrenn tað byrjar á fleiri.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"Stutti kekklisti toymisins um, hvat „liðugt“ merkir, eitt nú roynt og greitt frá, áðrenn eitt kort verður latið tær. Tvíburin, Definition of Ready, sigur, nær eitt kort er nóg greitt at byrja uppá.","also":["Definition of Ready","DoD","DoR","Definition of Done"]},{"id":"retro","g":"agile","word":"Retro","text":"Eitt regluligt afturlit á, hvussu toymið arbeiðir, fyri at semjast um eitt ella tvey ting at gera betur næstu ferð. Stytt fyri retrospective. Í AI-gile skjýtur ein retro upp eina broyting í arbeiðshættum toymisins, og tú sigur Go ella Ikki enn.","also":["retrospektiv","afturlit"]},{"id":"swarm","g":"agile","word":"Sverm","text":"Øll á dekk: nógv fólk leggja annað arbeiði frá sær fyri saman at rætta eitt áríðandi mál, til tað er loyst. Í AI-gile hjálpa øll toymi til við einari verkætlan, meðan aðrar verkætlanir bíða.","also":["sværm","swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Í Scrum persónurin, sum hjálpir toyminum at arbeiða væl: ruddar tað, sum forðar teimum, heldur fundum á rættari kós og vegleiðir í góðum vanum, uttan at stjórna nøkrum. Í AI-gile sær Lead Scrum Master kort, sum sita føst, eggjar toymunum og minnir teg á tað, sum bíðar, tvørtur um allar verkætlanir.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Ein máti at arbeiða í smáum stigum: byggja eitt sindur, vísa veruligt úrslit ofta, læra av tí, sum fólk siga, og broyta ætlanina so hvørt, heldur enn at leggja alt til rættis frammanundan.","also":["Agile menning","agile arbeiðsmáti"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"Ein stutt yvirlýsing, skrivað í 2001 av fólki, sum gera ritbúnað. Hon setur fólk, úrslit, sum rigga, nært samstarv við kundar og at taka ímóti broytingum fram um tungar ætlanir og skjalaarbeiði.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall (fossmodell)","text":"Tann eldri arbeiðsmátin: at leggja alt til rættis, so byggja alt, so royna alt, eitt stig í senn. Broytingar seint í gongdini eru trupular og dýrar.","also":["fossmodell","waterfall","waterfall model"]},{"id":"iteration","g":"agile","word":"Iteratión (umfar)","text":"Eitt umfar, har tú byggir okkurt, kannar tað og betrar tað. Agile arbeiði er ein røð av hesum, og ein sprint er eitt slag av teimum.","also":["iteratiónir","iteration","iterations"]},{"id":"increment","g":"agile","word":"Inkrement","text":"Ein nýggjur partur, sum riggar og verður lagdur afturat vøruni í einum sprinti ella arbeiðsumfari, og sum passar saman við tað, sum longu var.","also":["increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Ein vælumtóktur Agile-arbeiðsmáti: eitt lítið toymi arbeiðir í stuttum sprintum móti einum máli, við ásettum leiklutum og nøkrum føstum fundum til at leggja til rættis, kanna og betra."},{"id":"scrumteam","g":"agile","word":"Scrum-toymi","text":"Lítli bólkurin, sum ger arbeiðið í Scrum: ein vøruábyrgdari, ein Scrum Master og menningarfólkini.","also":["Scrum-toymi"]},{"id":"ceremonies","g":"agile","word":"Scrum-hendingar","text":"Føstu fundirnir í Scrum: sprint-ætlan, dagligi scrum, sprint-umrøða og retro. Nógv kalla teir seremoniir.","also":["seremoniir","Scrum-seremoniir","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint-ætlan","text":"Fundurin í byrjanini av einum sprinti, har toymið semst um, hví sprinturin hevur týdning, hvørji kort tað skal taka, og hvussu tað skal byrja.","also":["ætlanarfundur"]},{"id":"sprintgoal","g":"agile","word":"Sprint-mál","text":"Ein setningur, sum sigur, hvat ein sprint er til. Smáar uppgávur kunnu broytast á vegnum, bara málið verður rokkið.","also":["sprint-mál"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"Kortini, sum eru vald til hendan sprintin, saman við ætlan toymisins fyri, hvussu tey skulu gerast.","also":["sprint backlogs","sprint-backlog"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"Allur listin, í raðfylgju, yvir alt, sum kann byggjast til vøruna, við tí týdningarmesta ovast. Hann broytist so hvørt, sum tú lærir.","also":["product backlogs","vøru-backlog"]},{"id":"productgoal","g":"agile","word":"Vørumál","text":"Størra úrslitið, sum vøran arbeiðir móti, og sum hjálpir toyminum at velja, hvat skal gerast næst.","also":["vørumál"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"At ganga backloggin ígjøgnum regluliga fyri at rudda, býta sundur, raðfesta og leggja smálutir afturat kortunum, so tey eru klár at taka. Eisini kallað backlog grooming.","also":["backlog grooming","refinement","backlog-snyrting"]},{"id":"sprintreview","g":"agile","word":"Sprint-umrøða","text":"Ein fundur í endanum á einum sprinti, har toymið vísir, hvat tað gjørdi liðugt, og hoyrir, hvat fólk hugsa, fyri at avgera, hvat kemur næst.","also":["sprint-umrøður"]},{"id":"demo","g":"agile","word":"Demo","text":"At vísa liðugt arbeiði, sum riggar, beinleiðis fyri teimum, sum bóðu um tað.","also":["demos","framsýning"],"noTip":1},{"id":"timebox","g":"agile","word":"Tíðarkarmur (timebox)","text":"Ein ásett tíð til okkurt. Tá ið hon er úti, steðgar tú, hóast ikki alt er gjørt.","also":["tíðarkarmar","timebox","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"Hvussu nógv arbeiði eitt toymi vanliga fær liðugt í einum sprinti, brúkt til at ætla, hvussu nógv tað skal taka næstu ferð. Tað er ikki eitt stigatal fyri, hvussu hart fólk arbeiða.","also":["team velocity","toymisferð"]},{"id":"capacity","g":"agile","word":"Arbeiðsorka (capacity)","text":"Hvussu nógv arbeiði toymið kann taka sær av í einum tíðarskeiði, tá ið frídagar og onnur størv eru roknað frá.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown-línurit","text":"Eitt línurit, sum vísir arbeiðið, ið er eftir í einum sprinti, fara niður dag fyri dag. Verður linjan verandi flat, situr okkurt fast.","also":["burndown","burn-down chart","burndown chart"]},{"id":"burnup","g":"agile","word":"Burnup-línurit","text":"Eitt línurit, sum vísir liðugt arbeiði fara upp yvir tíð, við síðuna av øllum tí ætlaða, so tú sært, nær tú kemur á mál.","also":["burnup","burn-up chart","burnup chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban-borð","text":"Borðið sjálvt: ein súla fyri hvørt stig í arbeiðinum, og kortini flyta seg yvir frá súlu til súlu.","also":["Kanban-borð"]},{"id":"pullsys","g":"agile","word":"Dráttarskipan","text":"Ein arbeiðsmáti, har nýtt arbeiði bert byrjar, tá ið onkur hevur pláss at taka tað, heldur enn at tað verður trýst inn á ein fullan disk.","also":["pull system","pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"Hvussu lættliga arbeiðið flytur seg yvir borðið. Gott flow merkir, at kortini halda fram at flyta seg heldur enn at hópast upp.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Gjøgnumgongdartíð","text":"Hvussu leingi tað tekur frá, at onkur biður um okkurt, til tað er liðugt.","also":["gjøgnumgongdartíðir","lead time"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"Hvussu leingi eitt kort tekur frá tí, at arbeiðið veruliga byrjar á tí, til tað er liðugt.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"Hvussu nógv kort verða liðug um vikuna, ella í einari aðrari ásettari tíð.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Fløskuhálsur","text":"Tað eina stigið, har arbeiðið hópast upp og seinkar alt aftan fyri, líkt og tranga hálsin á eini fløsku.","also":["fløskuhálsar","bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Svimjibreyt","text":"Ein røð tvørtur um borðið, sum savnar kort av einum slagi, til dømis áríðandi arbeiði ella kortini hjá einum toymi.","also":["svimjibreytir","swimlane"]},{"id":"lean","g":"agile","word":"Lean","text":"Ein arbeiðsmáti, sum skerur spill burtur (alt, sum ikki hjálpir kundanum) og heldur arbeiðinum í gongd."},{"id":"waste","g":"agile","word":"Spill","text":"Í Lean alt, sum krevur orku, men ikki hjálpir kundanum, til dømis at bíða, at gera arbeiði umaftur ella at byggja ting, sum eingin brúkar.","noTip":1},{"id":"kaizen","g":"agile","word":"Støðug umbøting","text":"At gerast eitt sindur betri alla tíðina við smáum, regluligum broytingum og síðan kanna, um tær hjálptu. Retros eru ein máti at gera tað. Eisini kallað kaizen.","also":["kaizen","continuous improvement"]},{"id":"selforg","g":"agile","word":"Sjálvskipað toymi","text":"Eitt toymi, sum sjálvt avger, hvussu arbeiðið verður gjørt, heldur enn at fáa at vita stig fyri stig, hvat tað skal gera.","also":["sjálvskipandi","sjálvstýrt toymi"]},{"id":"crossfunc","g":"agile","word":"Tvørfakligt toymi","text":"Eitt toymi, sum hevur allan førleikan, ið tað hevur brúk fyri at gera arbeiðið liðugt sjálvt, til dømis sniðgeving, bygging og royndir.","also":["tvørfakligt","cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"Ein stutt kanning við tíðarkarmi til at svara einum spurningi, áðrenn tú bindur teg til veruliga arbeiðið.","also":["spikes"]},{"id":"rework","g":"agile","word":"Umgerð","text":"At gera arbeiði aftur, tí tað ikki var rætt fyrstu ferð.","also":["umgjørt"]},{"id":"safe","g":"agile","word":"Skalerað Agile (SAFe)","text":"Mátar at brúka Agile tvørtur um nógv toymi í einum stórum felagsskapi. SAFe (Scaled Agile Framework) er eitt væl kent dømi.","also":["skalerað Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Mappan hjá verkætlanini við kotu og fullari søgu um commits. Hon kann vera á telduni hjá tær, á GitHub, ella bæði.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Ein sær lina av arbeiði í koduni, so at broytingar kunnu gerast uttan at nerta við høvuðsútgávuna.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Ein goymd mynd av koduni, við einum stuttum notati um, hvat broyttist. Tú kanst altíð fara aftur til eina.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"At senda tínar goymdu støðumyndir (commits) frá hesi teldu til felags avritið á netinum, til dømis GitHub, so tær eru trygdargoymdar, og onnur kunnu fáa tær."},{"id":"merge","g":"build","word":"Merge","text":"At leggja broytingarnar frá einari branch inn í eina aðra, vanliga aftur í høvuðsútgávuna."},{"id":"pr","g":"build","word":"Pull request","text":"At biðja um, at broytingarnar í eini branch verða kannaðar og lagdar saman við høvuðsútgávuna. Summar síður kalla tað merge request.","also":["PR","PRs","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"At rudda koduna uttan at broyta, hvat hon ger: minni fílur, greiðari navn, minni endurtøka."},{"id":"bug","g":"build","word":"Bug","text":"Okkurt, sum ikki riggar, sum tað skal.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Peer review","text":"Eitt annað eygapar: onkur annar enn høvundurin kannar arbeiðið, áðrenn tað kemur til tín, so færri feilir sleppa ígjøgnum. Í AI-gile kannar ein annar AI hvørt kort.","also":["code review","kodukanning"]},{"id":"code","g":"build","word":"Kota","text":"Skrivaðar leiðbeiningar, sum siga telduni, hvat hon skal gera. Eisini kallað keldukota.","also":["keldukota"],"noTip":1},{"id":"proglang","g":"build","word":"Forritanarmál","text":"Eitt mál til at skriva kotu í, til dømis JavaScript, Python ella Java. Ymisk mál hóska til ymisk arbeiði.","also":["forritanarmál"]},{"id":"developer","g":"build","word":"Forritari (dev)","text":"Onkur, sum skrivar og broytir kotu. Eisini kallaður forritari ella software engineer.","also":["forritari","forritarar","menningarfólk","developer","developers","programmer","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Forrit, sum koyra á teldum og telefonum, í mun til maskinurnar sjálvar (hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Stytt fyri applikatión: eitt forrit, sum fólk brúka til at fáa okkurt gjørt, á einari telefon, einari teldu ella í einum vevlesara.","also":["app","appir","applikatión","applikatiónir"],"noTip":1},{"id":"webapp","g":"build","word":"Vevapp","text":"Eitt app, sum koyrir í einum vevlesara, so einki skal installerast.","also":["vevappir","web app"]},{"id":"frontend","g":"build","word":"Front end","text":"Parturin av einum appi, sum tú sært og trýstir á: skermarnir, knøttarnir og orðini, ofta í tínum vevlesara.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"Parturin av einum appi aftan fyri tjaldið, sum goymir dáturnar og ger arbeiðið, tá ið tú trýstir á okkurt, til dømis kannar loyniorðið hjá tær.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"At arbeiða bæði við front end og back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"Brúkaraflata (UI)","text":"Tað, sum ein persónur sær og brúkar á skerminum: uppsetingin, knøttarnir, valmyndirnar og tekstirnir.","also":["UI","user interface","brúkaraflata"]},{"id":"ux","g":"build","word":"Brúkaraupplivan (UX)","text":"Hvussu tað kennist at brúka okkurt: lætt, greitt og hugnaligt, ella ørkymlandi og seint.","also":["UX","user experience","brúkaraupplivan"]},{"id":"accessibility","g":"build","word":"Atkomuligleiki (a11y)","text":"At gera ting brúkilig fyri øll, eisini fólk, sum ikki síggja væl, ikki kunnu brúka eina mús ella brúka ein skermlesara.","also":["a11y","atkomuligleiki"]},{"id":"responsive","g":"build","word":"Responsivt snið","text":"At fáa síður at passa og rigga væl á hvørji skermstødd sum helst, frá telefon til ein stóran skerm.","also":["responsivt"]},{"id":"designsys","g":"build","word":"Sniðskipan","text":"Eitt felags sett av litum, skriftum, knøttum og reglum, so hvør skermur sær út og riggar á sama hátt.","also":["sniðskipanir","design system"]},{"id":"architecture","g":"build","word":"Bygnaður","text":"Heildarlagið á einari skipan: hvørjir høvuðspartarnir eru og hvussu teir práta saman."},{"id":"database","g":"build","word":"Dátugrunnur (DB)","text":"Ein skipað goymsla av upplýsingum, líkt og eitt sera megnugt rokniark, ið appið kann lesa og broyta.","also":["dátugrunnur","dátugrunnar","database","DB"]},{"id":"schema","g":"build","word":"Dátugrunnsskema","text":"Uppsetingin á einum dátugrunni: hvørjar talvur av upplýsingum hann hevur og hvat fer í hvørja.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Stytt fyri structured query language: málið, sum verður brúkt til at spyrja nógvar dátugrunnar um upplýsingar ella til at broyta tær.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Dátur","text":"Upplýsingar, sum ein telda goymir, til dømis navn, bíleggingar ella stillingar.","also":["dátusett"],"noTip":1},{"id":"server","g":"build","word":"Ambætari","text":"Ein telda, sum altíð er tendrað og svarar umbønum frá øðrum teldum, til dømis sendir eina vevsíðu, tá tú vitjar hana.","also":["ambætarar","server"]},{"id":"client","g":"build","word":"Klientur (client)","text":"Síðan, sum biður um okkurt, vanliga tín vevlesari ella títt app, sum tosar við ein ambætara. Í vinnulívinum merkir tað eisini bara ein kunda.","also":["klientar","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Stytt fyri application programming interface: ein fastur matseðil av umbønum, sum eitt forrit kann gera til eitt annað, til dømis at spyrja eina veðurtænastu um forsøgnina í dag.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endapunkt","text":"Ein lutur á matseðlinum hjá einum API: ein vevbústaður, sum eitt forrit kann kalla fyri at fáa ella senda okkurt.","also":["endapunkt","endpoint"]},{"id":"integration","g":"build","word":"Samantenging (integration)","text":"At knýta tvær skipanir saman, so tær rigga saman, til dømis at handilin hjá tær sendir bíleggingar til bókhaldsforritið.","also":["samantengingar","integration","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Eitt boð, sum ein skipan av sær sjálvari sendir til eina aðra í somu løtu, sum okkurt hendir, til dømis “gjald móttikið”.","also":["webhooks"]},{"id":"library","g":"build","word":"Savn","text":"Tilreidd kota, sum onkur annar hevur skrivað, og sum tú kanst endurnýta heldur enn at skriva hana frá grundini.","also":["library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Rammaverk","text":"Ein tilreiddur bygnaður til at byggja eitt app, sum avger nógv um, hvussu kotan er løgd upp, líkt og ein húsagrind, ið tú fyllir út.","also":["rammaverk","framework"]},{"id":"sdk","g":"build","word":"Menningarsett (SDK)","text":"Ein kassi við amboðum, kotu og dømum til at byggja forrit til ein pall ella eina tænastu.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Avhengi í ritbúnaði","text":"Eitt savn ella amboð, sum kotan hjá tær hevur brúk fyri fyri at rigga. At halda tey dagførd hevur týdning fyri trygdina.","also":["software dependency","software dependencies"]},{"id":"package","g":"build","word":"Pakki","text":"Ein bunki av tilreiddari kotu, sum tú kanst installera og brúka í eini verkætlan.","also":["pakkar","package"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Pakkastýring","text":"Eitt amboð, sum heintar og dagførir pakkarnar, sum kotan hjá tær er bundin av. npm er eitt vanligt.","also":["pakkastýringar","package manager","npm"]},{"id":"git","g":"build","word":"Git","text":"Tað mest brúkta amboðið til at goyma søguna um kotubroytingar, sum commits og branches."},{"id":"github","g":"build","word":"GitHub","text":"Ein heimasíða, sum goymir Git repos á netinum, so toymi kunnu deila kotu, endurskoða broytingar og fylgja við arbeiði."},{"id":"vcs","g":"build","word":"Útgávustýring","text":"At goyma fulla søgu um hvørja broyting á fílunum, so tú kanst síggja, hvør broytti hvat, og fara aftur, um tørvur er. Git ger hetta.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Klona","text":"At gera eitt fult avrit, sum er títt egna, av einum repo, við allari søguni, á telduni hjá tær.","also":["klonað","clone","cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"At heinta nýggjastu commits frá felags avritinum (sum GitHub) til telduna hjá tær. Mótsetningurin til push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Høvuðsgrein","text":"Tann opinbera útgávan av kotuni, sum øll arbeiða frá, ofta kallað main ella master.","also":["master branch","main branch"]},{"id":"conflict","g":"build","word":"Merge-konflikt","text":"Tá ið tvær broytingar nerta við somu linjur á ymiskan hátt, so teldan ikki dugir at leggja tær saman, og ein persónur má velja.","also":["merge conflicts","merge conflict"]},{"id":"diff","g":"build","word":"Diff","text":"Eitt yvirlit, sum vísir neyvt, hvat broyttist ímillum tvær útgávur: linjur, sum eru lagdar afturat, og linjur, sum eru tiknar burtur.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Títt egna avrit av repo hjá onkrum øðrum, sum tú kanst broyta, uttan at tað ávirkar teirra.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"Eitt stutt forrit, sum ger eitt arbeiði av sær sjálvum, til dømis at rudda fílur ella at seta appið í gongd.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Bygging","text":"At umseta kotuna til okkurt, sum er klárt at koyra, ella tað klára úrslitið sjálvt.","also":["byggingar","build","builds"],"noTip":1},{"id":"compile","g":"build","word":"Umseta","text":"At umseta kotu, sum fólk hava skrivað, til eitt snið, sum teldan kann koyra beinleiðis.","also":["compile","compiler"]},{"id":"cli","g":"build","word":"Boðlinja (CLI)","text":"Ein tekstgluggi, har tú skrivar boð til telduna heldur enn at trýsta. Eisini kallað terminalur.","also":["command line","command-line","CLI","terminal","boðlinja"]},{"id":"config","g":"build","word":"Konfiguratión (config)","text":"Innstillingarnar, sum stýra, hvussu forrit virkar, goymdar skildar frá kotuni, so tær eru lættar at broyta.","also":["config","configuration","konfiguratión"],"noTip":1},{"id":"envvar","g":"build","word":"Umhvørvisbroytil","text":"Ein innstilling, sum verður givin einum forriti, tá ið tað byrjar, ofta brúkt til bústaðir ella loyniorð, so tey ikki verða skrivað inn í kotuna.","also":["umhvørvisbroytlar","environment variable","env var"]},{"id":"debugging","g":"build","word":"Villuleiting","text":"At finna út av, hví okkurt ikki riggar, og síðan rætta tað.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Parforritan (pair programming)","text":"Tvey fólk (ella ein persónur og ein AI), sum arbeiða saman við somu kotu: annað skrivar, og hitt kannar.","also":["pairing","pair programming"]},{"id":"docs","g":"build","word":"Skjalfesting (docs)","text":"Skrivaðar útskýringar um, hvussu okkurt virkar ella hvussu tað verður brúkt.","also":["documentation","docs","skjalfesting"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Fyrsta fílan at lesa í einum repo: hvat verkætlanin er, og hvussu hon verður sett í gongd.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Gomul skipan (legacy)","text":"Ein eldri skipan, sum enn verður brúkt, og sum er trupul at broyta, ofta tí fá enn skilja hana.","also":["legacy systems","legacy code","arvaskipan"]},{"id":"techdebt","g":"build","word":"Tøknisk skuld","text":"Stuttleiðir, sum spara tíð nú, men gera seinni broytingar tyngri, líkt og eitt lán, ið rentur hópast á. Refactoring rindar hana niður.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"Ein kanning av, at okkurt riggar, sum tað skal. Summar royndir koyrir teldan av sær sjálvari hvørja ferð, kotan broytist; aðrar eru, at tú roynir eitt liðugt kort, áðrenn tú góðkennir tað.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Stytt fyri quality assurance: alt, sum verður gjørt fyri at tryggja, at arbeiðið er rætt, áðrenn tað fer live. Í AI-gile merkir tað sjálvvirkandi kanningarnar: tá ið QA er reytt, er okkurt miseydnað, og tað kann ikki fara live, fyrr enn tað er rættað.","also":["góðskueftirlit","góðskutrygging","quality assurance"]},{"id":"testpile","g":"test","word":"Royndabunki","text":"Tey lidnu kortini, sum bíða eftir, at tú roynir tey, eitt eftir annað. Góðtak eitt ella send tað aftur við eini notu, og tað næsta kemur fram.","also":["royndabunkar","royndabunka"]},{"id":"autotest","g":"test","word":"Sjálvvirkandi roynd","text":"Ein kanning, sum teldan koyrir av sær sjálvari hvørja ferð, kotan broytist, fyri at fanga feilir tíðliga.","also":["automated tests","automatic tests","sjálvvirkandi royndir"]},{"id":"manualtest","g":"test","word":"Handroynd","text":"Ein persónur, sum roynir arbeiðið við hondini fyri at síggja, um tað riggar, sum tað skal.","also":["manual tests","manual testing","handroyndir"]},{"id":"unittest","g":"test","word":"Eindarroynd","text":"Ein lítil sjálvvirkandi kanning av einum lítlum parti av kotu fyri seg.","also":["unit tests","eindarroyndir"]},{"id":"integtest","g":"test","word":"Samansetingarroynd","text":"Ein kanning, sum vísir, at fleiri partar virka rætt saman, ikki bara ein í senn.","also":["integration tests","integration test","samansetingarroyndir"]},{"id":"endtoend","g":"test","word":"Enda-til-enda roynd (E2E)","text":"Ein roynd, sum fer fram sum ein veruligur brúkari frá byrjan til enda, til dømis at skráseta seg, keypa og gjalda.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"Góðkenningarroynd hjá brúkarum (UAT)","text":"Fólkini, sum bóðu um arbeiðið, royna tað sjálv og siga, um tað ger tað, sum tey hava brúk fyri. Royndabunkin er útgávan hjá AI-gile av hesum.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Afturgongd","text":"Okkurt, sum riggaði áður, men fór í ólag eftir eina broyting. Afturgongdarroyndir kanna, at tað gamla enn riggar.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Roykroynd","text":"Ein sera skjót kanning av, um høvuðstingini yvirhøvur rigga, til dømis beint eftir at ein broyting er farin live. Miseydnast hon, so steðga og hygg eftir.","also":["smoke tests","smoke test"]},{"id":"exploratory","g":"test","word":"Kannandi royndir","text":"At royna vøruna frítt og pota í hana á ymiskan hátt fyri at finna trupulleikar, sum ætlaðar kanningar høvdu sloppið framvið.","also":["exploratory test","exploratory tests","exploratory testing"]},{"id":"testcase","g":"test","word":"Royndartilfelli","text":"Ein skrivað støða at royna: stigini, og hvat eigur at henda.","also":["test cases","test case","royndartilfelli"]},{"id":"coverage","g":"test","word":"Royndardekking","text":"Hvussu stórur partur av kotuni verður kannaður av sjálvvirkandi royndum. Meira er vanliga tryggari, men høg dekking einsamøll prógvar ikki, at tað riggar væl.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Royndardátur","text":"Uppdiktaðar dømisupplýsingar, brúktar undir royndum, so ongar privatar upplýsingar um veruligt fólk verða sýndar.","also":["test fixtures","test data"]},{"id":"edgecase","g":"test","word":"Jaðartilfelli","text":"Ein óvanlig støða á markinum, til dømis eitt tómt oyðublað ella eitt navn við apostrofi, har tingini ofta fara í ólag.","also":["edge cases","edge case","jaðartilfelli"]},{"id":"happypath","g":"test","word":"Glaða leiðin","text":"Vanliga leiðin, har alt gongur rætt. Góðar royndir royna eisini ringu leiðirnar."},{"id":"perftest","g":"test","word":"Avrikisroynd","text":"At kanna, hvussu skjótt okkurt er, og hvussu væl tað klárar tyngsli.","also":["performance test","performance tests","performance testing"]},{"id":"loadtest","g":"test","word":"Tyngdarroynd","text":"At kanna, hvussu ein skipan klárar seg, tá ið nógv fólk brúka hana í senn.","also":["load test","load tests","load testing"]},{"id":"sectest","g":"test","word":"Trygdarroynd","text":"At leita eftir veikleikum, sum kundu latið onkran misbrúka eina skipan ella síggja tað, sum ikki er ætlað teimum.","also":["security test","security tests","security testing"]},{"id":"accesstest","g":"test","word":"Atkomuligleikaroynd","text":"At kanna, at fólk við ymiskum førleikum kunnu brúka vøruna, eisini við skermlesara ella bert við knappaborði.","also":["accessibility test","accessibility testing"]},{"id":"linting","g":"test","word":"Linting","text":"Ein sjálvvirkandi kanning, sum finnur sannlík mistøk og slurvaðan stíl í kotu, sum ein stavingarkanning fyri forrit.","also":["linter","lint"]},{"id":"static","g":"test","word":"Statisk greining","text":"At kanna kotu fyri trupulleikum við at lesa hana sjálvvirkandi, uttan at koyra hana.","also":["static code analysis","static analysis"]},{"id":"flaky","g":"test","word":"Óstøðug roynd","text":"Ein roynd, sum onkuntíð eydnast og onkuntíð miseydnast, uttan nakra sjónliga orsøk, so tú kanst ikki líta fult á hana.","also":["flaky tests","flaky test"]},{"id":"repro","g":"test","word":"Endurskapa (repro)","text":"At fáa eina villu at henda aftur við vilja við at fylgja somu stigum, so hon kann kannast og rættast. At skriva stigini niður er tað nyttugasta í eini villufrágreiðing.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Álvarsstig","text":"Hvussu ring ávirkanin av einum trupulleika er, frá lítlum ergilsi til at alt steðgar.","also":["severity level","severity"]},{"id":"deploy","g":"change","word":"Deploy","text":"At avrita eina nýggja útgávu av forritinum út á teldurnar, sum koyra tað, til dømis eitt royndaravrit ella tænastuna, sum er live."},{"id":"release","g":"change","word":"Útgáva","text":"Ein navngivin bólkur av lidnum arbeiði, sum fer live saman, við stuttum notum um, hvat er broytt. 🚀 Útgávur skrivar notarnar út frá teimum lidnu kortunum.","also":["útgávur","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"At fara aftur til seinastu útgávuna, sum riggaði, tá ið ein nýggj elvir til trupulleikar. Í AI-gile savnar Roll back afturgerðarstigini, sum eru skrivað við hvørja broyting, í ein kekklista.","also":["rulla aftur","rullað aftur","fara aftur"]},{"id":"live","g":"change","word":"Live","text":"Tann veruliga útgávan, sum fólk nýta, ímóti einum avriti at royna ting á. Menningarfólk kalla tað eisini production.","also":["framleiðsla","production","í gongd"],"noTip":1},{"id":"change","g":"change","word":"Broyting","text":"Ein ætlað broyting í nøkrum, sum fólk líta á, skrivað niður fyrst: hvat, hví, váðin, nær og hvussu hon verður angrað. Byrja eina við 🔀 Bið um broyting.","also":["broytingar","broytingarumbøn","broytingarumbønir"],"noTip":1},{"id":"risk","g":"change","word":"Váði","text":"Okkurt, sum kann fara skeivt, givið stig eftir, hvussu sannlíkt og hvussu ringt tað hevði verið. ⚠️ Váðar goymir teir í einum lista, hægstu stig fyrst, hvør við einum degi at hyggja aftur.","also":["váðar","váðaskrá"]},{"id":"chgwin","g":"change","word":"Broytingargluggi","text":"Tíðirnar, tá ið broytingar sleppa at fara live, til dømis eitt kvirt týsdagskvøld. Uttan fyri ein glugga kann eitt broytingarkort ikki verða liðugt, uttan so at tað er ein neyðstøða.","also":["broytingargluggar"]},{"id":"gonogo","g":"change","word":"Go / No go","text":"Ein seinasta kanning beint áðrenn ein broyting fer live: hvør persónur, sum skal góðkenna, sigur Go ella No go. Tað fer bert fram, tá ið øll siga Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Góðkenning","text":"At bíða eftir einum ja, áðrenn arbeiðið byrjar. Eitt kort, sum ein vinur stovnar, ella ein broyting, bíðar í ✅ Góðkenningar, til tú góðkennir ella avvísir tað.","also":["góðkenningar"]},{"id":"quiettime","g":"change","word":"Kvirr tíð","text":"Eitt tíðarskeið, til dømis undir eini beinleiðis útsending, eini demo ella um náttina, tá ið einki fer live. Toymini halda fram at arbeiða og royna, men at fara live bíðar, til tað er av. Aðrastaðni verður tað kallað change freeze.","also":["kvirrar tíðir","broytingarstøðgur","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Ein arbeiðsmáti, har fólkini, sum byggja ritbúnað, og fólkini, sum reka hann, arbeiða sum eitt toymi, við nógvari sjálvvirkni, so broytingar ofta og trygt fara live."},{"id":"cicd","g":"change","word":"CI/CD (støðug samanseting og útlevering)","text":"Broytingarnar hjá øllum verða ofta lagdar saman í høvuðsútgávuna og kannaðar sjálvvirkandi hvørja ferð (støðug samanseting), so forritið altíð er klárt at fara live við einum knøttatrýsti (støðug útlevering).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"Eitt stig longri enn støðug útlevering: hvør broyting, sum klárar kanningarnar, fer live av sær sjálvari, uttan nakran knøtt at trýsta á.","also":["continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"Sjálvvirkandi røðin av stigum, sum ein broyting fer ígjøgnum á vegnum til live, til dømis bygging, roynd og síðan deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Umhvørvi","text":"Eitt sundurskilt avrit av skipanini til eitt ávíst endamál, til dømis eitt at byggja í, eitt at royna í og tað, sum er live.","also":["environments","environment"],"noTip":1},{"id":"devenv","g":"change","word":"Menningarumhvørvi","text":"Avritið, sum ein forritari arbeiðir í, ofta á egnu telduni, har tað ikki skaðar nakran at oyðileggja ting.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Royndarumhvørvi","text":"Eitt sundurskilt avrit av skipanini, bert brúkt til royndir, so veruliga tænastan ikki verður rørd.","also":["test environments","test environment"]},{"id":"staging","g":"change","word":"Staging","text":"Eitt seinasta avrit, sett upp júst sum tað, ið er live, til eina endaliga kanning, áðrenn ein broyting fer live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Byggingarúrslit","text":"Fílan ella pakkin, sum ein bygging ger, klár at verða goymd, kannað ella sett live.","also":["build artifacts","build artifact"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Ein áríðandi rætting, sett skjótt live uttan fyri vanligu ætlanina, tí okkurt týdningarmikið er í ólagi.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"Ein lítil dagføring, sum rættar eina villu ella lukkar eitt trygdarhol. Tað hevur týdning at seta trygdarpatches á skjótt.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Útgávunummar","text":"Eitt merki sum 2.4.1, sum sigur, hvørja útgávu tú hevur. Ofta broytist fyrsta talið við stórum broytingum og seinasta við smáum rættingum.","also":["version numbers","semantic versioning","útgávunummur"]},{"id":"relnotes","g":"change","word":"Útgávuboð","text":"Ein stuttur einfaldur listi yvir, hvat broyttist í einari útgávu, til tey, sum brúka hana, við rættingum og kendum mørkum. Eisini kallað changelog.","also":["changelog","change log","release notes"]},{"id":"flag","g":"change","word":"Feature flag (funktiónsskifti)","text":"Ein tendra/sløkkja-knøttur fyri eina funktión, so nýtt arbeiði kann fara live fjalt og verða tendrað (ella sløkt aftur) uttan nýggja útgávu.","also":["feature flags","feature toggle","feature toggles","feature flag"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"At rætta eina ringa útgávu við skjótt at geva út eina nýggja, rættaða útgávu í staðin fyri at fara aftur til tað gamla.","also":["rolling forward","rolled forward","roll forward"]},{"id":"canary","g":"change","word":"Canary release (kanarifuglaútgáva)","text":"At seta eina broyting live fyri ein lítlan bólk fyrst og fyri øll bert tá ið alt tykist í lagi. Nevnd eftir kanarifuglunum, sum námuarbeiðarar tóku við sær niður í námuna sum tíðliga ávaring.","also":["canary releases","canary release","kanarifuglaútgáva"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"At hava tvey avrit av live-skipanini og flyta fólk yvir á tað nýggja í einum vetfangi, so tú kanst flyta tey beinanvegin aftur, um tað gongur galið.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"Deploy uttan steðg","text":"At seta eina nýggja útgávu live, uttan at tænastan nakrantíð steðgar fyri brúkararnar.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Broytingarstýring","text":"At hjálpa broytingum at eydnast: at vega váðan, fáa røttu góðkenningina og velja eina góða tíð. Eisini kallað change management.","also":["change management","change enablement"]},{"id":"cab","g":"change","word":"Broytingarráð (CAB)","text":"Ein bólkur, sum hyggur at týdningarmiklum broytingum og semst um, hvørt og nær tær sleppa at fara fram.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standardbroyting","text":"Ein broyting við lágum váða, gjørd á sama royndu hátt hvørja ferð, so hon er góðkend frammanundan.","also":["standard changes","standard change"]},{"id":"normchange","g":"change","word":"Vanlig broyting","text":"Ein broyting, sum skal kannast og góðkennast, áðrenn hon fer fram.","also":["normal changes","normal change"]},{"id":"emergchange","g":"change","word":"Neyðarbroyting","text":"Ein broyting, sum má henda beinanvegin fyri at rætta ella forða fyri álvarsomum trupulleikum, við eini líka skjótari góðkenning.","also":["emergency changes","emergency change"]},{"id":"automation","g":"change","word":"Sjálvvirkni","text":"At fáa telduna at gera eitt endurtikið arbeiði av sær sjálvari, so tað gongur skjótari og verður gjørt á sama hátt hvørja ferð.","also":["automated","automation"],"noTip":1},{"id":"infra","g":"change","word":"Grundbygnaður","text":"Maskinurnar, netini og tænasturnar, sum forrit koyra á.","also":["infra","infrastructure"]},{"id":"iac","g":"change","word":"Grundbygnaður sum kota (IaC)","text":"At lýsa tínar ambætarar og innstillingar í fílum, sum verða goymdar saman við kotuni, so tær kunnu byggjast upp aftur júst eins hvørja ferð.","also":["IaC"]},{"id":"cloud","g":"change","word":"Skýggið (cloud)","text":"At leiga teldur, goymslu og tænastur frá einum stórum veitara umvegis alnetið, heldur enn at eiga egnar maskinur.","also":["skýggið","cloud","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Skýggjaveitari","text":"Eitt felag, sum leigar út rokniorku um alnetið, til dømis Amazon Web Services (AWS), Microsoft Azure ella Google Cloud.","also":["skýggjaveitarar","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Staðið, har appið ella heimasíðan hjá tær býr og koyrir, so fólk kunnu koma til hana, vanliga leigað frá einum felagi.","also":["hýsing"]},{"id":"domain","g":"change","word":"Domeni (domain name)","text":"Vevbústaðurin, sum fólk skriva, til dømis example.com. Tú leigar hann eitt ár í senn, so hann má endurnýggjast.","also":["domeni","domain names","domain","domain name"]},{"id":"dns","g":"change","word":"DNS","text":"Stytt fyri domain name system: bústaðabókin hjá alnetinum, sum umsetir eitt navn sum example.com til bústaðin hjá røttu telduni.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"Ein lokaður pakki, sum hevur eitt app og alt, tað hevur brúk fyri, so tað koyrir eins á hvørji teldu sum helst. Docker er best kenda amboðið.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtuell maskina (VM)","text":"Ein sýndartelda, sum koyrir inni í eini veruligari, so ein stór maskina kann virka sum nógvar.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"At koyra kotu uttan at hava nakran ambætara at røkja: veitarin koyrir hana, tá ið tørvur er, og tú rindar fyri tað, tú brúkar."},{"id":"lb","g":"change","word":"Tyngdarbýtari","text":"Okkurt, sum býtir vitjandi út á fleiri ambætarar, so eingin teirra fær ov nógv at gera.","also":["load balancers","load balancer"]},{"id":"cache","g":"change","word":"Cache","text":"Ein hentug goymsla av nýligum úrslitum, ið verður hildin tætt við, so tað sama ikki skal heintast ella roknast út aftur. At tøma hana kann rætta síður, sum tykjast gamlar.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Innihaldsflutningsnet (CDN)","text":"Eitt heimsvítt sett av ambætarum, sum goyma avrit av tínum síðum og myndum nær tínum vitjandi, so tær verða skjótt innlisnar.","also":["CDN"]},{"id":"migration","g":"change","word":"Migratión (flyting)","text":"At flyta dátur ella skipanir frá eini gamlari uppseting til eina nýggja, ella at broyta varisliga, hvussu ein dátugrunnur er lagdur upp.","also":["migrations","database migration","migration"]},{"id":"service","g":"run","word":"Tænasta","text":"Okkurt, tú hevur bygt, sum fólk líta á, eitt nú ein heimasíða ella ein app, sum verður ansað eftir, so tað heldur fram at virka. Set kross við „Henda verkætlan er ein tænasta“ og sig, hvat hon bjóðar, hvør nýtir hana, og hvør hevur vakt.","also":["tænastur","tænastu"]},{"id":"uptimepct","g":"run","word":"Uppitíð","text":"Hvussu stóran part av tíðini ein tænasta riggar, vanliga sum prosent. 99,9% loyvir enn umleið 43 minuttir niðri um mánaðin.","also":["uptime percentage","uptime"]},{"id":"uptime","g":"run","word":"Uppi-tíðar eftirlit","text":"Eitt sjálvvirkandi eftirlit, hvørjar fáar minuttir, at tín tænasta enn svarar. Miseydnast tað fleiri ferðir á rað, letur AI-gile sjálvt eitt hendingarkort upp.","also":["uptime checks","uppitíðarkanningar"]},{"id":"statuspage","g":"run","word":"Støðusíða","text":"Ein almenn síða, sum vísir, um ein tænasta virkar (grønt, appelsingult ella reytt), við nýggjastu dagføringini, so tey, ið nýta hana, kunnu hyggja í staðin fyri at spyrja.","also":["støðusíður","støðusíðuni","status page"]},{"id":"desk","g":"run","word":"Tænastuskrivborð","text":"Har spurningar og fráboðanir frá teimum, sum brúka tænastuna hjá tær, koma inn. AI-gile flokkar hvørja sum umbøn, hending ella hugskot og sigur frá, tá ið hon líkist okkurt, sum longu er fráboðað.","also":["tænastuskrivborð","skrivborð","service desk","hjálparskrivborð"]},{"id":"svcrequest","g":"run","word":"Tænastuumbøn","text":"Onkur biður um okkurt vanligt, t.d. eina nýggja kontu ella eina lítla hjálp, heldur enn at boða frá, at okkurt er í stykkjum. Hon bíðar eftir sínari tørn; ein hending fer fram um.","also":["tænastuumbønir"]},{"id":"incident","g":"run","word":"Hending","text":"Okkurt, sum er í ólagi ella ikki riggar rætt fyri fólkini, sum brúka tað júst nú, til dømis at heimasíðan er niðri ella ógvuliga sein. Eitt 🔥 hendingarkort sleppur fram um í røðini: at fáa tað at rigga aftur kemur fyrst.","also":["hendingar","hendingin","incident"]},{"id":"major","g":"run","word":"Stór hending","text":"Ein stór hending: nógv fólk rakt, ella pengar ella dátur í vanda. Ein knøttur setir øll toymi á hana (sverm), vekir tann, ið hevur vakt, og biður um eina støðudagføring hvønn 30. minutt.","also":["stórar hendingar","major incident"]},{"id":"oncall","g":"run","word":"Vakt","text":"At vera tann, sum svarar, tá ið okkurt fer í stykkir, eisini um náttina. Hvør tænasta hevur ein toymislim á vakt, sum verður vaktur fyrst við hennara hendingum.","also":["á vakt","vaktin","on-call","on call"]},{"id":"replyby","g":"run","word":"Svartíð","text":"Hvussu leingi eitt kort má bíða eftir fyrsta svari, til dømis ein tíma fyri eina hending. Eftir tað fær tað eitt reytt ur, so einki verður gloymt í kvirrum. Verður eisini kallað svarmál.","also":["svartíðir","svarmál"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Ein stutt eftirmeting eftir eina hending: hvat hendi, hvat hjálpti, og hvat skal broytast, uttan at geva nøkrum skyldina. Ein hending kann ikki verða latin aftur uttan hana.","also":["post-mortems","postmortem","eftirmeting"]},{"id":"problem","g":"run","word":"Trupulleiki","text":"Tann fjalda orsøkin aftan fyri eina ella fleiri hendingar. Eitt 🧩 trupulleikakort savnar hendingar, sum koma aftur og aftur, so orsøkin verður funnin og rættað fyri alla tíð.","also":["trupulleikar","trupulleikin"],"noTip":1},{"id":"rootcause","g":"run","word":"Rótarorsøk","text":"Tann veruliga orsøkin til, at okkurt fór í stykkir, ikki bara tað, tú sást fara skeivt. Rætta rótarorsøkina, og hendingin kemur ikki aftur.","also":["rótarorsøkir","grundarsøk"]},{"id":"workaround","g":"run","word":"Bráðabirgdaloysn","text":"Ein háttur at halda tingunum koyrandi, til tann veruliga rættingin er klár, eitt nú at endurbyrja okkurt, tá ið tað steðgar. Hon er skrivað á trupulleikakortið, so eingin skal finna út av henni aftur.","also":["bráðabirgdaloysnir","neyðloysn","workaround"]},{"id":"knownerror","g":"run","word":"Kendur feilur","text":"Ein trupulleiki, har orsøkin er kend, men sum ikki er rættaður enn, vanliga við eini bráðabirgdaloysn skrivaðari niður. 🧩 Kendir feilir vísir teir, so øll brúka bráðabirgdaloysnina heldur enn at grava aftur.","also":["kendir feilir","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Stig fyri stig vegleiðing at rætta ein kendan slag av trupulleika, so tað verður gjørt á sama hátt, skjótt, hvørja ferð. Eftir eina stóra hending kann toymið skjóta upp eina, sum tú góðkennir.","also":["runbooks","rakstrarvegleiðing"]},{"id":"ci","g":"run","word":"Konfiguratiónsting","text":"Eitt ting, sum tænastan hjá tær byggir á, t.d. ein ambætari, eitt domeni, eitt sertifikat, ein lykil ella ein veitari. 🗂️ Konfiguratiónsting vísir tey fyri hvørja tænastu, so tú sært, hvat ein hending ávirkar, og hvat skal endurnýggjast ella afturgoymast.","also":["konfiguratiónstingini","konfiguratiónsting","CI"]},{"id":"expiry","g":"run","word":"Útgangsdagur","text":"Dagurin, tá ið okkurt steðgar at rigga, uttan so at tað verður endurnýggjað, til dømis trygdarsertifikatið á eini heimasíðu ella vevbústaðurin hjá henni. AI-gile fylgir við hesum døgunum og ger eitt kort til at endurnýggja hvørt teirra 30 dagar frammanundan, so einki steðgar óvæntað.","also":["útgangsdagar","útgongd","eftirlit við útgongd"]},{"id":"backup","g":"run","word":"Trygdaravrit","text":"Eitt goymt avrit av tínum dátum frá áður, at falla aftur á, um okkurt fer burt ella verður skatt. AI-gile ger eitt trygdaravrit av tínum borðum hvønn dag.","also":["trygdaravritið","backup","backups"]},{"id":"restore","g":"run","word":"Endurskapan","text":"At seta dátur aftur úr einum trygdaravriti. Eitt trygdaravrit telur bara veruliga, tá ið tú veitst, at tað kann endurskapast, so tað loysir seg at royna tað nú og tá.","also":["endurskapa","endurskapað","restore"]},{"id":"svcreview","g":"run","word":"Tænastukanning","text":"Eitt afturlit á ein mánað hjá eini tænastu: hendingar, sum vórðu latnar upp og rættaðar, hvussu skjótt fólk fingu svar, uppitíð og brúkt tokens. Mánaðarlig kanning vísir tað fyri hvørja tænastu.","also":["tænastukanningar","mánaðarlig kanning","mánaðarligar kanningar"]},{"id":"accessreview","g":"run","word":"Atgongdarkanning","text":"At kanna hvørjar 90 dagar, hvør framvegis sleppur inn: deilingarleinkjur, leiklutir hjá vinum og goymd loyniorð og lyklar. Tú varðveitir ella strikar hvørt, so gomul atgongd ikki liggur eftir.","also":["atgongdarkanningar"]},{"id":"improvements","g":"run","word":"Betringarlisti","text":"Alt, sum toymið hevur avgjørt at gerast betri til, á einum stað: retro-uppskot, kanningarhandlingar og trupulleikarættingar, hvørt við sínari støðu. Tú finnur tað undir 📈 Betringar.","also":["betringarlistar","betringar"]},{"id":"tokencap","g":"run","word":"Token-tak","text":"Eitt mánaðarligt mark fyri, hvussu nógv tokens agentarnir hjá eini tænastu sleppa at brúka. Við 80% fært tú eina ávaring; við 100% bíðar bakgrundsarbeiðið hjá teimum til næsta mánað, ella til tú hækkar takið.","also":["token-tøk","mánaðarligt token-tak"]},{"id":"svcmgmt","g":"run","word":"Tænastustýring","text":"Alt, sum skal til fyri at halda eina tænastu nyttuga og í gongd fyri fólkini, sum líta á hana, dag eftir dag."},{"id":"itil","g":"run","word":"ITIL","text":"Ein víða brúkt leiðbeining í góðari tænastustýring, sum fevnir um hendingar, trupulleikar og broytingar. Navnið stóð upprunaliga fyri IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT-tænastustýring (ITSM)","text":"At reka tøkni sum eina tænastu fyri fólk, við greiðum mátum at taka sær av umbønum, hendingum, broytingum og betringum.","also":["ITSM"]},{"id":"managed","g":"run","word":"Rikin tænasta (managed service)","text":"Ein tænasta, sum onkur annar rekur og røkir fyri teg, eftir eini avtalu um, hvussu væl hon skal rigga.","also":["managed services","managed service"]},{"id":"svcowner","g":"run","word":"Tænastuábyrgdari","text":"Persónurin, sum svarar fyri eina tænastu sum heild: hvussu væl hon virkar, hvat hon kostar og hvussu hon batnar.","also":["service owners","service owner"]},{"id":"sla","g":"run","word":"Tænastustigsavtala (SLA)","text":"Eitt skrivað lyfti til kundar um, hvussu væl ein tænasta fer at rigga, til dømis “uppi 99,9% av tíðini” ella “svarað innan ein tíma”, ofta við peningi aftur, um lyftið verður brotið.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Tænastustigsmál (SLO)","text":"Egna málið hjá toyminum fyri, hvussu væl ein tænasta eigur at rigga yvir eitt tíðarskeið, vanliga sett eitt sindur strangari enn SLA fyri at vera á tryggu síðuni.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Tænastustigsmátari (SLI)","text":"Tann veruliga mátingin, sum tú kannar móti einum máli, til dømis partin av vitjanum, har síðan kom væl fram.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Tøkleiki","text":"Um fólk kunnu brúka eina tænastu, tá tey hava brúk fyri henni, ofta mátað sum uppitíð.","also":["tøkleiki","high availability","availability"]},{"id":"downtime","g":"run","word":"Niðurtíð","text":"Tíð, tá ein tænasta ikki riggar ella er sløkt, ætlað ella ikki.","also":["down time","downtime"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"Tann lítla nøgdin av feilum, sum álitismálið hjá tær loyvir. So leingi nakað er eftir, kanst tú taka váðar við broytingum; tá ið tað er brúkt upp, fert tú spakuligari fram.","also":["error budgets","feilkvota"]},{"id":"outage","g":"run","word":"Avbrot","text":"Ein tíð, tá ið ein tænasta er niðri ella í stórum ólagi fyri brúkararnar.","also":["outages","outage"]},{"id":"degraded","g":"run","word":"Skerd","text":"Riggar, men illa: seint, ella við nøkrum pørtum, sum ikki rigga.","also":["degraded service","degraded"]},{"id":"monitoring","g":"run","word":"Eftirlit","text":"At fylgja sjálvvirkandi við eini tænastu alla tíðina, so trupulleikar verða funnir, helst áðrenn brúkararnir leggja merki til teir.","also":["monitoring"]},{"id":"observability","g":"run","word":"Observability","text":"Hvussu væl tú uttanífrá kanst siga, hvat fer fram inni í eini skipan, við at brúka loggar hennara, tøl og slóðir.","also":["o11y","observability"]},{"id":"log","g":"run","word":"Logg","text":"Ein løpandi dagbók, sum eitt forrit heldur um, hvat tað ger, brúkt til at finna út, hvat fór galið.","also":["logs","logging","log"],"noTip":1},{"id":"trace","g":"run","word":"Slóð","text":"Ein skráseting av, hvussu ein einstøk umbøn ferðast gjøgnum ymsu partarnar í einari skipan, stig fyri stig, og vísir, hvar hon varð seinkað.","also":["traces","tracing","trace"]},{"id":"latency","g":"run","word":"Seinkan","text":"Hvussu leingi tað tekur at svara, til dømis bíðitíðin, frá tú trýstir, til síðan kemur til sjóndar.","also":["latency"]},{"id":"alert","g":"run","word":"Ávaring","text":"Eitt sjálvvirkandi boð um, at okkurt tørvar athygli, til dømis at heimasíðan ikki svarar.","also":["alerts","alerting","alert"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Ávaringarmøði (alert fatigue)","text":"Tá ið so nógvar ávaringar eru, at fólk fara ikki at ansa eftir teimum, eisini teimum týdningarmiklu.","also":["alarm fatigue","alert fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"Ein skermur, sum vísir týdningarmestu tølini og støðurnar í einum eygnabragdi.","also":["dashboards","yvirlitsborð"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"At ringja til ella vekja tann, sum hevur vakt, í skundi um ein trupulleika.","also":["paged"]},{"id":"escalation","g":"run","word":"Eskalering","text":"At fáa onkran við størri førleika ella myndugleika uppí, tá ið ein sak ikki kann loysast á verandi stigi, ella ikki nóg skjótt.","also":["escalate","escalated","escalation"]},{"id":"triage","g":"run","word":"Triage","text":"At sortera komandi mál skjótt eftir, hvussu áríðandi og týdningarmikil tey eru, so tað versta verður tikið fyrst.","also":["triaged"]},{"id":"impact","g":"run","word":"Ávirkan","text":"Hvussu nógv okkurt ávirkar fólk: hvussu nógv og hvussu illa.","noTip":1},{"id":"urgency","g":"run","word":"Hast","text":"Hvussu skjótt okkurt skal handfarast. Ávirkan og hast saman seta raðfestingina.","noTip":1},{"id":"plevels","g":"run","word":"Raðfestingarstig (P1, P2…)","text":"Merki fyri, hvussu áríðandi eitt mál er. P1 er tað álvarsamasta og krevur atgerð beinanvegin.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Seðlarøð","text":"Listin yvir umbønir og hendingar, sum bíða eftir at verða tiknar.","also":["ticket queues","ticket queue"]},{"id":"tiers","g":"run","word":"Fyrsta og annað stig","text":"Stig í stuðlinum: fyrsta stig tekur telefonina og rættar einfaldar ting; annað stig hevur djúpari førleika til truplari mál. Eisini kallað tier 1 og tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Hendingarleiðari","text":"Tann eini persónurin, sum leiðir arbeiðið við eini hending, so øll vita, hvør avger, og hvør ger hvat.","also":["incident commanders","incident commander"]},{"id":"responsetime","g":"run","word":"Svartíð","text":"Hvussu leingi tað tekur, áðrenn onkur fyrstu ferð tekur eina umbøn ella hending.","also":["response times","response time"]},{"id":"resolution","g":"run","word":"Loysnartíð","text":"Hvussu leingi tað tekur at loysa eina umbøn ella hending heilt, frá tí at boðað verður frá, til tað er rættað.","also":["resolution times","time to resolve","resolution time"]},{"id":"mttr","g":"run","word":"Miðal endurreisingartíð (MTTR)","text":"Í miðal, hvussu leingi tað tekur at fáa eina tænastu at rigga aftur, eftir at hon er farin í ólag. MTTR kann merkja nakað ymiskt, so sig, hvat tú mátar.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Miðaltíð millum feilir (MTBF)","text":"Í miðal, hvussu leingi ein tænasta koyrir, áðrenn okkurt fer í ólag.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Konfiguratiónsdátugrunnur (CMDB)","text":"Listin yvir øll tíni konfiguratiónsting og hvussu tey eru knýtt saman, so tú sært, hvat er bundið av hvørjum.","also":["CMDB"]},{"id":"asset","g":"run","word":"Ogn","text":"Alt av virði, sum tú eigur ella rindar fyri at reka tænastuna, til dømis ein fartelda, eitt ritbúnaðarloyvi ella eitt domeni.","also":["assets","asset"],"noTip":1},{"id":"capplan","g":"run","word":"Orkuætlan","text":"At tryggja, at nóg mikið verður av rokniorku, goymslu og fólki til tað, sum kemur.","also":["capacity plan","capacity planning"]},{"id":"scaling","g":"run","word":"Skalering","text":"At klára fleiri brúkarar við at geva eini maskinu meira orku (skalera upp) ella leggja fleiri maskinur afturat (skalera út).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Rakstrartrygd","text":"Ætlanir fyri at halda týdningarmiklu tingunum í gongd, tá ið okkurt stórt fer galið, til dømis at missa eina skrivstovu, ein týdningarmiklan veitara ella teldurnar.","also":["business continuity plan","business continuity"]},{"id":"dr","g":"run","word":"Endurreisn eftir vanlukku (DR)","text":"Ætlanin og amboðini til at fáa eina tænastu aftur eftir okkurt álvarsamt, til dømis at missa eina heila dátumiðstøð.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Endurreisingartíðarmál (RTO)","text":"Longsta tíðin, ein tænasta kann vera niðri eftir eina vanlukku, áðrenn hon aftur skal rigga.","also":["RTO"]},{"id":"rpo","g":"run","word":"Endurreisingarpunktsmál (RPO)","text":"Hvussu nógv av nýggjastu dátunum tú hevur ráð at missa, mátað í tíð. Ein RPO á ein tíma merkir trygdaravrit í minsta lagi hvønn tíma.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundans (varaloysn)","text":"At hava varaútgerð klára, til dømis ein annan ambætara, so ein feilur ikki steðgar tænastuni.","also":["redundancy"]},{"id":"failover","g":"run","word":"Skifti til varaskipan","text":"At skifta av sær sjálvum yvir á eina varaskipan, tá ið vanliga skipanin fer í ólag.","also":["fail over","failover"]},{"id":"spof","g":"run","word":"Einstakt feilpunkt (SPOF)","text":"Ein partur, sum tekur alt við sær niður, tá ið hann fer í ólag, tí einki vara er.","also":["single points of failure","SPOF","single point of failure"]},{"id":"maintwin","g":"run","word":"Viðlíkahaldsgluggi","text":"Ein ætlað tíð, tá ið ein tænasta kann verða steðgað ella vera sein orsakað av viðlíkahaldi, boðað brúkarunum frammanundan.","also":["maintenance windows","planned maintenance","maintenance window"]},{"id":"handover","g":"run","word":"Yvirlating","text":"At lata arbeiði, kunnleika og ábyrgd yvir til ein annan persón ella eitt annað toymi, so einki gloymist.","also":["yvirlatingar","handovers","handover"]},{"id":"kb","g":"run","word":"Kunnleikagrunnur","text":"Eitt savn av hjálpargreinum og svarum, til brúkarar og til toymið.","also":["knowledge bases","knowledge base"]},{"id":"csat","g":"run","word":"Nøgdsemi hjá kundum (CSAT)","text":"Eitt stigatal frá brúkarum, sum sigur, hvussu nøgd tey vóru, ofta spurt, eftir at ein umbøn er avgreidd.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Veitari","text":"Eitt uttanhýsis felag, sum tú ert bundin av, til dømis hýsingarveitarin hjá tær. Eisini kallað vendor ella triði partur.","also":["suppliers","vendor","vendors","third party","supplier"],"noTip":1},{"id":"retire","g":"run","word":"Niðurlegging av tænastu","text":"At sløkkja eina tænastu fyri alt, trygt: siga brúkarunum frá, handfara dátur og atgongd og steðga kostnaðinum.","also":["retiring a service"]},{"id":"eol","g":"run","word":"Lívsendi (EOL)","text":"Tá ein vøra ikki fær fleiri dagføringar ella stuðul frá framleiðaranum, so hon eigur at verða skift út.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"KT-trygd (cybersecurity)","text":"At verja skipanir og dátur, so eingin brýtur seg inn í tær, stjelur tær ella skaðar tær.","also":["KT-trygd","cyber security","cybersecurity"]},{"id":"authn","g":"sec","word":"Samleikaváttan (authentication)","text":"At kanna, hvør ein persónur er, vanliga við einum loyniorði ella eini kotu. Ofta stytt til authn.","also":["authn","authentication"]},{"id":"authz","g":"sec","word":"Heimild","text":"At kanna, hvat ein persónur hevur loyvi at gera, tá ið tú veitst, hvør hann er. Ofta stytt til authz.","also":["authz","authorization","authorisation"]},{"id":"mfa","g":"sec","word":"Fleirstigs samleikaváttan (MFA)","text":"At rita inn við tveimum ella fleiri prógvum, til dømis einum loyniorði og eini kotu á telefonini. Eisini kallað tvístigs (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Ein innritan fyri alt (SSO)","text":"At rita inn eina ferð fyri at koma inn í nógvar skipanir, til dømis at brúka arbeiðskontuna allastaðni.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Loyniorðsgoymsla (password manager)","text":"Eitt app, sum ger sterk loyniorð og minnist tey fyri teg.","also":["password managers","password manager"]},{"id":"secret","g":"sec","word":"Loyndarmál","text":"Eitt loyniorð, ein lykil ella onnur privat kota, sum eitt forrit brúkar til at koma inn í okkurt. Tað má ongantíð verða deilt ella skrivað inn í kotuna.","also":["secrets","secret"],"noTip":1},{"id":"apikey","g":"sec","word":"API-lykil","text":"Ein loynilig kota, sum loyvir einum forriti at brúka API hjá eini aðrari tænastu, og sum vísir, hvør brúkar (og rindar fyri) tað.","also":["API keys","API key"]},{"id":"accesstoken","g":"sec","word":"Atkomuteikn","text":"Eitt fyribils atgongdarkort, sum prógvar, at eitt forrit hevur loyvi at koma inn, so tað ikki hevur brúk fyri loyniorðinum hjá tær hvørja ferð. Ikki tað sama sum eitt AI-token.","also":["access tokens","access token"]},{"id":"encryption","g":"sec","word":"Bronglan (encryption)","text":"At brongla upplýsingar, so bert tann, sum hevur rætta lykilin, kann lesa tær.","also":["brongla","bronglað","encrypted","encrypt","encryption"]},{"id":"https","g":"sec","word":"HTTPS","text":"Tann trygga leiðin, sum vevsíður ferðast eftir, og sum hengilásurin í vevlesaranum vísir, so eingin ímillum kann lesa ella broyta tær."},{"id":"cert","g":"sec","word":"SSL/TLS-sertifikat","text":"Eitt talgilt samleikakort, sum loyvir eini heimasíðu at prógva, hvør hon er, og at brúka HTTPS. Tað gongur út, so tað má endurnýggjast.","also":["TLS certificate","SSL certificate","certificate","certificates","sertifikat"]},{"id":"permissions","g":"sec","word":"Atgongdarloyvi (permissions)","text":"Reglurnar fyri, hvør hevur loyvi at síggja ella broyta hvat.","also":["permission","permissions"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Minst møguliga atgongd","text":"At geva hvørjum persóni ella forriti bert tann atgongd, tey veruliga hava brúk fyri, og bert so leingi, tey hava brúk fyri henni.","also":["principle of least privilege","least privilege"]},{"id":"rbac","g":"sec","word":"Leiklutsbundin atgongd (RBAC)","text":"At geva atgongd eftir leiklutum, sum áskoðari ella ritstjóri, heldur enn persón fyri persón.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Veikleiki","text":"Ein veikleiki, sum onkur kundi brúkt til at bróta seg inn ella gera skaða.","also":["vulnerabilities","vulnerability"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Ein veikleiki, sum árásarar kenna, áðrenn framleiðararnir hava havt nakra tíð til at rætta hann.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Skaðaforrit","text":"Skaðiligur ritbúnaður, til dømis virus, gjørdur til at skaða, njósna ella stjala.","also":["malware"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Skaðaforrit, sum læsir fílurnar hjá tær og krevur pening fyri at lata tær upp aftur. Góð trygdaravrit eru besta verjan.","also":["ransomware attack","loysigjaldsforrit"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fals boð, sum royna at narra teg til at lata loyniorð ella pening frá tær ella at lata upp okkurt skaðiligt.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Sosial manipulatión","text":"At narra fólk, heldur enn teldur, til at geva atgongd, til dømis ein fals uppringing frá “KT-stuðlinum”."},{"id":"firewall","g":"sec","word":"Eldveggur","text":"Ein vaktari, sum avger, hvør netferðsla sleppur inn ella út.","also":["firewalls","firewall"]},{"id":"vpn","g":"sec","word":"VPN","text":"Stytt fyri virtual private network: ein privat, bronglað leið umvegis alnetið, ofta brúkt til at koma trygt til arbeiðsskipanir.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Yvirfyllingarárás (DoS, DDoS)","text":"At fløða eina tænastu við so nógvari falskari ferðslu, at veruligt fólk ikki fær brúkt hana. DDoS merkir, at ferðslan kemur frá nógvum teldum í senn.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Inntrongdarroynd (pen test)","text":"At leiga vinaligar serfrøðingar at royna at bróta seg inn, so veikleikar verða funnir, áðrenn veruligir álopsmenn finna teir.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Trygdarkanning","text":"Ein neyv kanning av, hvussu væl okkurt er vart, eftir einum lista yvir góða siðvenju.","also":["security audits","security audit"]},{"id":"threatmodel","g":"sec","word":"Hóttanargreining (threat modelling)","text":"At hugsa ígjøgnum, hvør kundi gjørt álop á okkurt, hvussu, og hvat tú hevði gjørt fyri at steðga teimum.","also":["threat model","threat modeling","threat modelling"]},{"id":"breach","g":"sec","word":"Dátubrot","text":"Tá ið privatar upplýsingar sleppa út til fólk, sum ikki skulu hava tær, ella verða mistar ella broyttar uttan loyvi.","also":["data breaches","data breach"]},{"id":"pii","g":"sec","word":"Persónsdátur","text":"Allar upplýsingar um ein persón, sum kann kennast aftur, til dømis navn, teldupostbústaður ella staðseting. Eisini kallað PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Evropeiska lógin um persónsdátur (Bretland hevur sína egnu útgávu): savna bert tað, tú hevur brúk fyri, goym tað trygt, og lat fólk síggja ella strika sínar.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Dátuvernd","text":"At fara rætt við persónsdátum og innan fyri lógina.","also":["data protection law","data protection"]},{"id":"privacypolicy","g":"sec","word":"Privatlívspolitikkur","text":"Ein almenn síða, sum sigur, hvørjar persónsdátur tú savnar, hví, og hvat tú gert við tær.","also":["privacy statement","privacy notice","privacy policy"]},{"id":"consent","g":"sec","word":"Samtykki","text":"Eitt greitt og frítt ja frá einum persóni til, at dátur hansara verða brúktar á ein ávísan hátt. Tað kann takast aftur nær sum helst.","also":["opt-in","consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Ein lítil fíla, sum ein heimasíða goymir í vevlesaranum hjá tær fyri at minnast ting, til dømis innritanina hjá tær. Fyri summar krevst títt samtykki fyrst.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Dátuminking","text":"Bert at savna og goyma tær persónsdátur, sum tú veruliga hevur brúk fyri til arbeiðið.","also":["data minimization","data minimisation"]},{"id":"retention","g":"sec","word":"Goymslutíð fyri dátur","text":"Hvussu leingi dátur verða goymdar, áðrenn tær verða strikaðar. At goyma tær ikki longur enn neyðugt er tryggari og ofta lógarkrav.","also":["retention period","data retention"]},{"id":"anon","g":"sec","word":"Anonymisering","text":"At broyta dátur so, at eingin í skili longur kann kennast aftur úr teimum.","also":["anonymised","anonymization","anonymous data","anonymisering"]},{"id":"pseudo","g":"sec","word":"Pseudonymisering","text":"At skifta navn og aðrar upplýsingar út við kotur, meðan ein lykil verður goymdur fyri seg, so tær kunnu knýtast saman aftur. Tað eru framvegis persónsdátur.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Dátuviðgerðarsáttmáli (DPA)","text":"Ein sáttmáli, sum sigur, hvussu ein veitari hevur loyvi at fara við persónsdátum fyri tína hond.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Ávirkanarmeting av dátuvernd (DPIA)","text":"Ein neyv gjøgnumgongd, áðrenn tú byrjar, av, hvussu ein ætlan um at brúka persónsdátur kann ávirka fólk, og hvussu váðarnir kunnu minkast.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Kanningarlogg","text":"Ein skráseting av, hvør gjørdi hvat og nær, so tað er møguligt at kanna atgerðir seinni.","also":["audit logs","audit trail","audit log"]},{"id":"compliance","g":"sec","word":"Regluhald (compliance)","text":"At fylgja lógum, reglum og standardum, sum galda fyri teg, og at kunna prógva, at tú ger tað.","also":["compliant","compliance"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Ein væl kendur altjóða standardur fyri at stýra upplýsingartrygd. Fyritøkur kunnu fáa sertifikat eftir honum.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Ein amerikonsk frágreiðing, kannað av uttanhýsis grannskoðarum, sum vísir, at eitt felag fer rætt við kundadátum.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"Ein AI, sum arbeiðir við einari uppgávu sjálvur: lesur kotuna, ger broytingar, koyrir kanningar og boðar frá. Arbeiðið hjá honum verður framvegis kannað.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"Lítlu tekstpartarnir, sum ein AI lesur og skrivar, umleið tríggjar fjórðingar av einum orði hvør. AI-brúk verður tald í tokens, so færri tokens lata meira vera eftir av tíni ætlan.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Eitt lítið boð, sum koyrir av sær sjálvum á eini ásettari løtu, til dømis tá ið ein AI-seta byrjar, so toymið hoyrir tínar viðmerkingar.","also":["hooks"]},{"id":"ai","g":"ai","word":"Vitlíki (AI)","text":"Telduskipanir, sum gera ting, sum vit vanliga halda krevja ein persón, til dømis at skriva, svara spurningum ella kenna myndir aftur.","also":["AI","artificial intelligence","vitlíki"],"noTip":1},{"id":"ml","g":"ai","word":"Maskinlæring (ML)","text":"Ein máti at fáa teldur at læra mynstur av nógvum dømum, í staðin fyri at geva teimum neyvar reglur.","also":["machine learning","maskinlæring"]},{"id":"model","g":"ai","word":"Modell","text":"Tann lærdi “heilin” í eini AI-skipan, bygdur við at læra av ótøljandi dømum. Modell eru ymisk í førleika, ferð og prísi.","also":["models","AI model","AI-modell"],"noTip":1},{"id":"llm","g":"ai","word":"Stórt málmodell (LLM)","text":"Eitt AI-modell, sum er lært á ógvuliga nógvum teksti, so tað kann lesa og skriva mál.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Skapandi AI","text":"AI, sum skapar nýggj ting, til dømis tekst, myndir ella kotu, heldur enn bert at sortera ella finna tey.","also":["GenAI","generative AI"]},{"id":"chatbot","g":"ai","word":"Chatbot (kjattbottur)","text":"Eitt forrit, sum tú tosar við á gerandismáli, antin við at skriva ella tala.","also":["chatbots","chatbot","kjattbottur"]},{"id":"prompt","g":"ai","word":"Boð til AI (prompt)","text":"Tað, sum tú gevur einum AI: spurningin ella leiðbeiningarnar hjá tær, saman við øllum, sum tú letur honum. Greiðari prompts geva vanliga betri svar.","also":["prompts","prompt"]},{"id":"prompteng","g":"ai","word":"Prompt-gerð","text":"Førleikin at skriva prompts, sum geva álítandi og nyttug úrslit.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"Skipanarprompt","text":"Bakgrundsleiðbeiningar, sum ein AI fær, áðrenn samrøðan byrjar, og sum áseta leiklut og reglur. Tær hava størri vekt enn tað, tú skrivar.","also":["system prompts","system instruction","system instructions","system prompt"]},{"id":"context","g":"ai","word":"Samanhangur","text":"Alt, sum AI sær, meðan hann arbeiðir: leiðbeiningarnar, tíni boð, fílur, hann hevur lisið, og fyrri svar.","noTip":1},{"id":"ctxwin","g":"ai","word":"Samanhangsgluggi","text":"Hvussu nógv ein AI kann hava í huga í senn, mátað í tokens. Út um tað verða eldri partar slepptir ella samandrignir.","also":["context windows","context window"]},{"id":"session","g":"ai","word":"Seta","text":"Ein arbeiðssamrøða við ein AI, frá byrjan til enda. Ein nýggj seta byrjar við reinum minni.","also":["sessions","session"],"noTip":1},{"id":"memory","g":"ai","word":"Minni","text":"Skrivaðar notur, sum ein AI goymir ímillum setur, so hann minnist tað, tú vilt, og fyrri avgerðir.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallusinatión","text":"Tá ein AI sigur okkurt, sum hoyrist sikkurt, men er uppspunnið ella skeivt. Kanna týdningarmiklar upplýsingar.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Læring","text":"At læra eitt modell upp við at vísa tí ógvuliga nógv dømi, áðrenn nakar brúkar tað.","also":["trained","training"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Læringardátur","text":"Dømini, sum eitt modell lærdi av. Kunnleikin hjá tí endar tann dagin, dáturnar vórðu savnaðar.","also":["training set","training data"]},{"id":"cutoff","g":"ai","word":"Kunnleikamark","text":"Dagurin, tá ið innbygdi kunnleikin hjá einum AI endar. Hann veit ikki um seinni ting, uttan so at hann leitar tey upp.","also":["training cutoff","knowledge cutoff"]},{"id":"finetune","g":"ai","word":"Fínstilling","text":"Eyka læring av einum verandi modelli við tínum egnu dømum fyri at gera tað betri til eitt ávíst arbeiði.","also":["fine-tune","fine-tuned","fine tuning","fine-tuning"]},{"id":"inference","g":"ai","word":"Inference (svarroknan)","text":"At eitt AI-modell veruliga verður brúkt til at svara okkurt, í mun til at tað verður lært upp.","also":["model inference","inference"]},{"id":"tooluse","g":"ai","word":"Amboðsbrúk","text":"Ein AI, sum kann gera ting, ikki bara práta: koyra boð, lesa fílur ella leita á vevnum, gjøgnum amboð, sum appið gevur honum.","also":["tool calling","tool call","tool calls","tool use"]},{"id":"subagent","g":"ai","word":"Undirhjálpari","text":"Ein hjálpar-AI, sum ein høvuðs-AI handar eitt minni arbeiði og síðan fær úrslitið aftur frá.","also":["subagents","sub-agent","subagent"]},{"id":"multiagent","g":"ai","word":"Fleiri agentar (multi-agent)","text":"Fleiri AI, sum arbeiða saman um eitt arbeiðsstykki, hvør við sínum parti, líkt og eitt lítið toymi.","also":["multi-agent system","multi-agent"]},{"id":"autonomy","g":"ai","word":"Sjálvstýri","text":"Hvussu nógv ein AI sleppur at gera sjálvur, áðrenn hann skal spyrja ein persón.","also":["autonomous","autonomy"]},{"id":"hitl","g":"ai","word":"Persónur í lykkjuni","text":"At hava ein persón við fyri at kanna ella góðkenna, tað AI ger, á týdningarmiklum løtum. Í AI-gile ert tað tú.","also":["human-in-the-loop","HITL","human in the loop"]},{"id":"guardrails","g":"ai","word":"Trygdarmørk (guardrails)","text":"Mørk og kanningar, sum halda atgerðunum hjá einum AI tryggum, til dømis at góðkenning krevst, áðrenn nakað fer live. Tey minka um váðan fyri feilum, men taka hann ikki burtur.","also":["guardrail","guardrails"]},{"id":"rag","g":"ai","word":"RAG (retrieval-augmented generation)","text":"At lata ein AI sláa upp í tínum egnu skjølum, áðrenn hann svarar, so svarini hvíla á tínum upplýsingum.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"At umseta tekst til ein lista av tølum, sum fangar týdningin, so ein telda kann finna ting, sum merkja nakað líknandi.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vektordátugrunnur","text":"Ein dátugrunnur bygdur til at leita í teimum listunum av tølum (embeddings) fyri at finna tilfar við líknandi týdningi.","also":["vector databases","vector store","vector database"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Ein felags máti at knýta amboð og dátukeldur at AI-appum, so ein AI kann brúka tey.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatur","text":"Ein innstilling fyri, hvussu djørv svarini hjá einum AI eru. Lág temperatur gevur støðugari svar, sum betur kunnu roknast við; høg gevur meira fjølbroytt svar. Hvørgin ger, at tað altíð hevur rætt.","also":["model temperature","temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Fleirmiðlað","text":"Førur fyri at arbeiða við meira enn einum slagi av upplýsingum, til dømis teksti, myndum og ljóði.","also":["multi-modal","multimodal"]},{"id":"evals","g":"ai","word":"Meting (eval)","text":"Ein ætlað roynd av, hvussu væl ein AI klárar seg við útvaldum dømum, so tú kanst bera modell ella prompts saman.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Skeivleiki","text":"Tá ið ein AI (ella ein persónur) hallar órættvíst til eina síðu, ofta orsakað av tí, hann lærdi av.","also":["biased","bias"],"noTip":1},{"id":"responsible","g":"ai","word":"Ábyrgdarfult AI","text":"At brúka AI rættvíst, trygt og ærliga, og fólk bera framvegis ábyrgdina av úrslitunum.","also":["ethical AI","responsible AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"Eitt narrispæl, har fjaldar leiðbeiningar á eini vevsíðu ella í eini fílu royna at fáa ein AI at gera okkurt, sum brúkarin ikki bað um.","also":["prompt injections","prompt injection"]},{"id":"ratelimit","g":"ai","word":"Umbønarmark","text":"Eitt hámark fyri, hvussu nógvar umbønir tú sleppur at senda til eina tænastu innan eina ásetta tíð. Fert tú upp um tað, mást tú bíða.","also":["rate limits","rate limited","rate limit"]},{"id":"usagelimit","g":"ai","word":"Brúksmark","text":"Hvussu nógv AI-arbeiði tín ætlan loyvir í einum tíðarskeiði; eftir tað steðgar tað ella kostar meira.","also":["usage limits","usage limit"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"At byggja forrit mestsum við at lýsa fyri einum AI, hvat tú vilt hava, og lata hann skriva kotuna.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Játtan","text":"Peningaupphæddin, sum er sett til viks til okkurt.","also":["budgets","budget"],"noTip":1},{"id":"costest","g":"money","word":"Kostnaðarmeting","text":"Tín besta giting um, hvat okkurt fer at kosta, áðrenn tú byrjar.","also":["cost estimates","cost estimate"]},{"id":"roi","g":"money","word":"Avkast av íløgu (ROI)","text":"Tað, sum tú fært aftur, í mun til tað, sum tú legði í. Er tað positivt, var tað vert at gera.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Samlaður eigarakostnaður (TCO)","text":"Alt, sum okkurt veruliga kostar gjøgnum alt sítt lív, ikki bara keypsprísin: rakstur, stuðul, uppgraderingar og at enda niðurlegging.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx og OpEx","text":"CapEx eru pengar, sum verða brúktir frammanundan til ting, sum tú varðveitir; OpEx eru løpandi útreiðslur, til dømis mánaðarligar rokningar.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Áskrift (abonnement)","text":"At rinda regluliga, vanliga um mánaðin ella árið, fyri at halda fram við at brúka okkurt.","also":["áskriftir","abonnement","subscriptions","subscription"],"noTip":1},{"id":"saas","g":"money","word":"Forrit sum tænasta (SaaS)","text":"Ritbúnaður, sum tú brúkar á netinum og rindar fyri við áskrift, meðan framleiðarin rekur hann fyri teg.","also":["SaaS"]},{"id":"payg","g":"money","word":"Rinda eftir brúk","text":"At rinda bert fyri tað, tú brúkar, til dømis skýggið ella AI-tokens.","also":["pay-as-you-go","usage-based pricing","pay as you go"]},{"id":"overage","g":"money","word":"Umframbrúk","text":"Brúk umframt tað, sum ætlanin hjá tær fevnir um, og sum kann kosta eyka.","also":["overages","overage charges","overage"]},{"id":"billingalert","g":"money","word":"Kostnaðarávaring","text":"Eitt boð, tá ið útreiðslur ella brúk náa einum stigi, sum tú valdi. Tað ávarar teg, men steðgar ikki altíð fleiri gjøldum.","also":["billing alerts","spending alert","billing alert"]},{"id":"freetier","g":"money","word":"Ókeypis stig","text":"Eitt ókeypis stig av eini goldnari tænastu, við avmarkingum. Hent at byrja við.","also":["free plan","free tier"]},{"id":"pricing","g":"money","word":"Prísætlan","text":"Ymsu pakkarnir, sum ein tænasta selur, hvør við sínum prísi og mørkum.","also":["pricing plans","price plan","pricing plan"]},{"id":"licence","g":"money","word":"Brúksloyvi (licence)","text":"Reglurnar fyri, hvussu tú hevur loyvi at brúka, avrita, broyta ella deila okkurt, sum onkur annar hevur gjørt, til dømis ritbúnað, skriftir ella myndir.","also":["brúksloyvi","licences","license","licenses","licence"],"noTip":1},{"id":"opensource","g":"money","word":"Open source (opin kelda)","text":"Ritbúnaður, har øll kunnu lesa kotuna, brúka hana og ofta broyta hana ókeypis, eftir reglunum í brúksloyvinum.","also":["open-source","open source software","OSS","open source"]},{"id":"osslicence","g":"money","word":"Open source-loyvi","text":"Reglurnar, sum fylgja við open source-kotu. Summi loyva tær at gera næstan alt (til dømis MIT); summi krevja, at tú eisini deilir tínar broytingar (til dømis GPL).","also":["open source licences","MIT licence","GPL","open source licence"]},{"id":"proprietary","g":"money","word":"Eigarastýrt","text":"Eigað av einum felagi og ikki frítt at avrita ella broyta. Mótsetningurin til open source.","also":["proprietary software","proprietary"]},{"id":"copyright","g":"money","word":"Upphavsrættur","text":"Lógarligi rætturin hjá einum skapara at ráða yvir avritum av verki sínum, eisini kotu og tekstum.","also":["copyrighted","copyright"],"noTip":1},{"id":"ip","g":"money","word":"Immateriell ogn (IP)","text":"Hugskot og skapanir, sum lógin metir sum ogn, til dømis kota, snið, nøvn og logo.","also":["intellectual property","IP"]},{"id":"tos","g":"money","word":"Brúkaratreytir","text":"Reglurnar, sum tú gongur við til, tá ið tú brúkar eina tænastu.","also":["terms and conditions","terms of use","terms of service"]},{"id":"contract","g":"money","word":"Sáttmáli","text":"Ein skrivlig avtala millum tveir partar, sum lógin stendur aftanfyri.","also":["contracts","contract"],"noTip":1},{"id":"sow","g":"money","word":"Arbeiðslýsing (SOW)","text":"Eitt skjal, sum neyvt sigur, hvørt arbeiði verður gjørt, nær tað skal vera liðugt, og fyri hvussu nógv.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Fastur prísur","text":"Ein avtalaður prísur fyri alt arbeiðið, sama hvussu leingi tað tekur.","also":["fixed-price","fixed price"]},{"id":"tm","g":"money","word":"Tími og tilfar","text":"At rinda fyri tímarnar, sum veruliga vórðu arbeiddir, og tað, sum veruliga varð brúkt, heldur enn ein fastan prís.","also":["T&M","time and materials"]},{"id":"invoice","g":"money","word":"Rokning","text":"Eitt skjal, sum biður um gjald fyri gjørt arbeiði ella veittar vørur.","also":["invoices","invoice"],"noTip":1},{"id":"lockin","g":"money","word":"Binding til veitara","text":"Tá ið tað er so trupult ella dýrt at fara frá einum veitara, at tú sleppur ikki undan honum.","also":["lock-in","vendor lock-in"]},{"id":"procurement","g":"money","word":"Innkeyp","text":"Tilgongdin at velja og keypa frá veitarum.","also":["procurement"]},{"id":"servicecredit","g":"money","word":"Tænastukredittur","text":"Pengar aftur ella avsláttur, sum tú fært, tá ein veitari ikki heldur SLA.","also":["service credits","service credit"]}]}};
